  { id:112, role:"Data Scientist", level:"Entry Level", category:"Culture Fit", difficulty:"Easy", question:"How do you stay current with developments in machine learning and statistics?", hint:"Papers, ArXiv, conferences, Kaggle, communities, courses, replicate papers." },
  { id:113, role:"Data Scientist", level:"Entry Level", category:"Culture Fit", difficulty:"Medium", question:"How do you handle pressure to show positive results when the data doesn't support it?", hint:"Data integrity is non-negotiable. Communicate null results professionally. Suggest next steps." },
  { id:114, role:"Data Scientist", level:"Entry Level", category:"Culture Fit", difficulty:"Hard", question:"How do you navigate the tension between being thorough and being fast in data work?", hint:"Define 'good enough' for the decision at hand. MVP analysis, iterate. Communicate uncertainty." },
  { id:115, role:"Data Scientist", level:"Entry Level", category:"Case Study", difficulty:"Easy", question:"How would you approach building a churn prediction model from scratch?", hint:"Define churn, feature engineering (recency, frequency, tenure), label creation, model selection, business threshold." },
  { id:116, role:"Data Scientist", level:"Entry Level", category:"Case Study", difficulty:"Medium", question:"How would you analyze the impact of a pricing change on customer behavior?", hint:"A/B test or diff-in-diff, control for seasonality, segment analysis, elasticity estimate." },
  { id:117, role:"Data Scientist", level:"Entry Level", category:"Case Study", difficulty:"Hard", question:"Design an experiment to test whether a new recommendation algorithm increases engagement.", hint:"Randomization unit (user vs session), metrics (CTR, dwell time, revenue), power analysis, guardrail metrics." },

  { id:118, role:"Data Scientist", level:"Mid Level", category:"Technical", difficulty:"Easy", question:"What is the difference between mean, median, and mode? When does each matter?", hint:"Mean: sensitive to outliers. Median: robust. Mode: categorical. Distribution shape drives the choice." },
  { id:119, role:"Data Scientist", level:"Mid Level", category:"Technical", difficulty:"Medium", question:"What's the difference between precision and recall? When do you prioritize each?", hint:"Precision: minimize false positives (spam filter). Recall: minimize false negatives (cancer detection)." },
  { id:120, role:"Data Scientist", level:"Mid Level", category:"Technical", difficulty:"Medium", question:"Explain gradient boosting. How does it differ from random forest?", hint:"Sequential weak learners vs parallel ensembles. Boosting reduces bias; bagging reduces variance." },
  { id:121, role:"Data Scientist", level:"Mid Level", category:"Technical", difficulty:"Hard", question:"How would you handle imbalanced datasets?", hint:"SMOTE, undersampling, class weights, threshold tuning, precision-recall curve over ROC." },
  { id:122, role:"Data Scientist", level:"Mid Level", category:"Technical", difficulty:"Hard", question:"Explain the difference between parametric and non-parametric statistical tests.", hint:"Parametric: assumes distribution (t-test). Non-parametric: rank-based (Mann-Whitney). Choose by data shape." },
  { id:123, role:"Data Scientist", level:"Mid Level", category:"Behavioral", difficulty:"Easy", question:"Describe a time you had to clean a particularly messy dataset. What was your approach?", hint:"Profiling, outliers, duplicates, type mismatches, domain knowledge validation, document decisions." },
  { id:124, role:"Data Scientist", level:"Mid Level", category:"Behavioral", difficulty:"Medium", question:"Tell me about a model you deployed. How did you monitor it after launch?", hint:"Data drift, concept drift, prediction distribution, business metrics, alerting, retraining triggers." },
  { id:125, role:"Data Scientist", level:"Mid Level", category:"Behavioral", difficulty:"Hard", question:"Describe a time your model performed well in offline evaluation but poorly in production.", hint:"Train-serve skew, data leakage in features, distribution shift, feedback loops." },
  { id:126, role:"Data Scientist", level:"Mid Level", category:"Situational", difficulty:"Easy", question:"Business wants a model in two weeks. You estimate four weeks. How do you handle this?", hint:"Scope MVP, baseline model first, communicate tradeoffs, deliver iteratively." },
  { id:127, role:"Data Scientist", level:"Mid Level", category:"Situational", difficulty:"Medium", question:"You discover your training data contains a target leak. What do you do?", hint:"Stop experiment, identify leak source, re-feature-engineer, retrain, check if model was deployed." },
  { id:128, role:"Data Scientist", level:"Mid Level", category:"Situational", difficulty:"Hard", question:"A model you built six months ago starts performing poorly. How do you diagnose it?", hint:"Data drift analysis, feature importance shift, label distribution change, upstream data pipeline issues." },
  { id:129, role:"Data Scientist", level:"Mid Level", category:"Culture Fit", difficulty:"Easy", question:"How do you collaborate with engineers to get models into production?", hint:"Understand their constraints, clean interfaces, containerization, reproducibility, communication of requirements." },
  { id:130, role:"Data Scientist", level:"Mid Level", category:"Culture Fit", difficulty:"Medium", question:"How do you handle a situation where stakeholders want to use a model you believe is not ready?", hint:"Quantify risk, propose guardrails, phased rollout, shadow mode, document and escalate if overruled." },
  { id:131, role:"Data Scientist", level:"Mid Level", category:"Culture Fit", difficulty:"Hard", question:"How do you maintain scientific rigor in a fast-moving business environment?", hint:"Pre-register hypotheses, document assumptions, use reproducible pipelines, resist p-hacking pressure." },
  { id:132, role:"Data Scientist", level:"Mid Level", category:"Case Study", difficulty:"Easy", question:"How would you build a simple sentiment analysis pipeline for customer reviews?", hint:"Text cleaning, tokenization, embedding, classifier (logistic/BERT), evaluation on labeled set, deployment." },
  { id:133, role:"Data Scientist", level:"Mid Level", category:"Case Study", difficulty:"Medium", question:"Design an A/B testing framework for a consumer app.", hint:"Randomization, sample size/power, metrics, duration, novelty effect, statistical significance, reporting." },
  { id:134, role:"Data Scientist", level:"Mid Level", category:"Case Study", difficulty:"Hard", question:"How would you build a real-time fraud detection system?", hint:"Feature engineering (velocity, graph features), model latency requirements, threshold tuning, feedback loop." },

  { id:135, role:"Data Scientist", level:"Senior Level", category:"Technical", difficulty:"Easy", question:"What is regularization and why is it used? Compare L1 vs L2.", hint:"L1 (Lasso): sparse, feature selection. L2 (Ridge): weight shrinkage. Elastic Net combines both." },
  { id:136, role:"Data Scientist", level:"Senior Level", category:"Technical", difficulty:"Medium", question:"How do you approach feature selection for a high-dimensional dataset?", hint:"Filter (correlation), wrapper (RFE), embedded (LASSO), PCA, domain knowledge, computational cost." },
  { id:137, role:"Data Scientist", level:"Senior Level", category:"Technical", difficulty:"Hard", question:"Explain causal inference methods and when you'd apply them over correlation analysis.", hint:"RCTs, IV, diff-in-diff, regression discontinuity, propensity score matching. When A/B test isn't possible." },
  { id:138, role:"Data Scientist", level:"Senior Level", category:"Behavioral", difficulty:"Easy", question:"How do you communicate model uncertainty to business stakeholders?", hint:"Confidence intervals, scenario analysis, sensitivity checks, avoid false precision, decision thresholds." },
  { id:139, role:"Data Scientist", level:"Senior Level", category:"Behavioral", difficulty:"Medium", question:"Tell me about a time you had to explain a complex model to non-technical executives.", hint:"Business impact first, analogy, visual summary, avoid math, focus on confidence and limitations." },
  { id:140, role:"Data Scientist", level:"Senior Level", category:"Behavioral", difficulty:"Hard", question:"Describe how you've built and maintained a data science roadmap for a product or team.", hint:"Align to business OKRs, prioritize by impact/effort, communicate to stakeholders, adapt iteratively." },
  { id:141, role:"Data Scientist", level:"Senior Level", category:"Situational", difficulty:"Easy", question:"Leadership wants a single metric to judge model performance. How do you handle this?", hint:"Educate on tradeoffs, propose primary + guardrail metrics, show cost of single metric gaming." },
  { id:142, role:"Data Scientist", level:"Senior Level", category:"Situational", difficulty:"Medium", question:"You're asked to make a prediction with very limited labeled data. What approaches do you consider?", hint:"Transfer learning, semi-supervised, weak supervision, active learning, data augmentation, few-shot." },
  { id:143, role:"Data Scientist", level:"Senior Level", category:"Situational", difficulty:"Hard", question:"Your team's ML platform is unreliable and slowing down experiments. How do you address this?", hint:"Document impact, make business case, propose incremental improvements, partner with platform team." },
  { id:144, role:"Data Scientist", level:"Senior Level", category:"Culture Fit", difficulty:"Easy", question:"How do you foster a culture of experimentation on a data science team?", hint:"Psychological safety for null results, fast iteration cycles, shared learnings, celebrate process not outcome." },
  { id:145, role:"Data Scientist", level:"Senior Level", category:"Culture Fit", difficulty:"Medium", question:"How do you ensure your team's models are ethical and unbiased?", hint:"Fairness metrics, subgroup analysis, diverse training data, audit process, stakeholder review." },
  { id:146, role:"Data Scientist", level:"Senior Level", category:"Culture Fit", difficulty:"Hard", question:"How do you balance research-quality work with the pace of a product team?", hint:"Time-box exploration, 80/20 rule, align research to near-term impact, publish internally." },
  { id:147, role:"Data Scientist", level:"Senior Level", category:"Case Study", difficulty:"Easy", question:"How would you design a recommendation system for a music streaming platform?", hint:"Collaborative filtering, content-based, hybrid, cold start, diversity vs accuracy, evaluation metrics." },
  { id:148, role:"Data Scientist", level:"Senior Level", category:"Case Study", difficulty:"Medium", question:"How would you measure the ROI of a machine learning model deployed in production?", hint:"Baseline comparison, uplift measurement, A/B or holdout group, cost of errors, business metric change." },
  { id:149, role:"Data Scientist", level:"Senior Level", category:"Case Study", difficulty:"Hard", question:"Design a multi-touch attribution model for a digital marketing team.", hint:"Last-click vs data-driven, Shapley values, Markov chains, time decay, cross-device challenges." },

  { id:150, role:"Data Scientist", level:"Lead / Manager", category:"Technical", difficulty:"Easy", question:"How do you evaluate the maturity of your team's ML infrastructure?", hint:"Reproducibility, versioning, monitoring, CI/CD for models, documentation, reuse." },
  { id:151, role:"Data Scientist", level:"Lead / Manager", category:"Technical", difficulty:"Medium", question:"How do you set standards for model documentation and reproducibility on your team?", hint:"Model cards, experiment tracking (MLflow), code versioning, environment snapshots, data versioning (DVC)." },
  { id:152, role:"Data Scientist", level:"Lead / Manager", category:"Technical", difficulty:"Hard", question:"How do you architect a scalable MLOps platform for a mid-sized data science team?", hint:"Feature store, experiment tracking, model registry, serving layer, monitoring, CI/CD pipelines." },
  { id:153, role:"Data Scientist", level:"Lead / Manager", category:"Behavioral", difficulty:"Easy", question:"How do you hire for a data science team? What do you look for beyond technical skills?", hint:"Curiosity, communication, business acumen, collaboration, intellectual honesty, growth mindset." },
  { id:154, role:"Data Scientist", level:"Lead / Manager", category:"Behavioral", difficulty:"Medium", question:"How do you manage a team with mixed skill levels in statistics and engineering?", hint:"Role clarity, pairing, personalized growth paths, avoid creating hierarchy from skill differences." },
  { id:155, role:"Data Scientist", level:"Lead / Manager", category:"Behavioral", difficulty:"Hard", question:"Tell me about a time you had to shut down a major project that wasn't producing results. How did you handle it?", hint:"Data-driven decision, team communication, preserve learnings, reframe as information not failure." },
  { id:156, role:"Data Scientist", level:"Lead / Manager", category:"Situational", difficulty:"Easy", question:"A data scientist on your team is consistently missing deadlines. What do you do?", hint:"1:1 conversation, understand root cause, set clear expectations, support/adjust scope, document." },
  { id:157, role:"Data Scientist", level:"Lead / Manager", category:"Situational", difficulty:"Medium", question:"Stakeholders want to use your team's model for a use case you believe it wasn't designed for. How do you respond?", hint:"Evaluate fit, quantify risk of misuse, propose proper evaluation, offer to build a targeted model." },
  { id:158, role:"Data Scientist", level:"Lead / Manager", category:"Situational", difficulty:"Hard", question:"You're asked to build an AI system that could create ethical risks. How do you navigate this?", hint:"Identify risks, document concerns, propose safeguards, escalate to leadership, involve ethics review." },
  { id:159, role:"Data Scientist", level:"Lead / Manager", category:"Culture Fit", difficulty:"Easy", question:"How do you build a collaborative relationship between data science and product teams?", hint:"Embed in product process, shared OKRs, translate business into data questions, regular syncs." },
  { id:160, role:"Data Scientist", level:"Lead / Manager", category:"Culture Fit", difficulty:"Medium", question:"What is your philosophy on using open source vs building custom ML tools?", hint:"Build only what differentiates, understand maintenance cost, community health, licensing." },
  { id:161, role:"Data Scientist", level:"Lead / Manager", category:"Culture Fit", difficulty:"Hard", question:"How do you create a culture of accountability for model outcomes in production?", hint:"Ownership model, monitoring ownership, post-mortems, success and failure reviews, on-call rotations." },
  { id:162, role:"Data Scientist", level:"Lead / Manager", category:"Case Study", difficulty:"Easy", question:"How would you structure a data science team to support 5 different product lines?", hint:"Embedded vs centralized tradeoffs, shared infrastructure, domain expertise, matrix org, coordination." },
  { id:163, role:"Data Scientist", level:"Lead / Manager", category:"Case Study", difficulty:"Medium", question:"Design a framework for prioritizing which ML projects to pursue.", hint:"Impact vs effort, data availability, model-ability, business alignment, risk, maintenance cost." },
  { id:164, role:"Data Scientist", level:"Lead / Manager", category:"Case Study", difficulty:"Hard", question:"How would you build an AI governance framework for a company deploying models at scale?", hint:"Model inventory, risk tiers, audit processes, fairness standards, explainability requirements, human oversight." },

  // ═══════════════════════════════════════════════════════════
  // PRODUCT MANAGER
  // ═══════════════════════════════════════════════════════════

  { id:165, role:"Product Manager", level:"Entry Level", category:"Technical", difficulty:"Easy", question:"What is an API and why should a PM understand how they work?", hint:"Understand what's technically feasible, better conversations with engineers, scope trade-offs." },
  { id:166, role:"Product Manager", level:"Entry Level", category:"Technical", difficulty:"Easy", question:"What is the difference between a bug and a feature request?", hint:"Bug: deviation from intended behavior. Feature: new capability. Prioritization differs for each." },
  { id:167, role:"Product Manager", level:"Entry Level", category:"Technical", difficulty:"Medium", question:"How do you write a good user story?", hint:"As a [user], I want [goal] so that [reason]. Includes acceptance criteria, edge cases, DoD." },
  { id:168, role:"Product Manager", level:"Entry Level", category:"Technical", difficulty:"Medium", question:"What is a product roadmap and how does it differ from a backlog?", hint:"Roadmap: strategic direction over time. Backlog: tactical list of work. Different audiences." },
  { id:169, role:"Product Manager", level:"Entry Level", category:"Technical", difficulty:"Hard", question:"How do you work with engineers to estimate the effort required for a feature?", hint:"Break down into tasks, involve engineers, T-shirt sizing or story points, spike for unknowns." },
  { id:170, role:"Product Manager", level:"Entry Level", category:"Technical", difficulty:"Hard", question:"Explain agile methodology. How does a PM's role differ in Scrum vs Kanban?", hint:"Scrum: sprint-based, backlog owner, ceremonies. Kanban: flow-based, WIP limits, continuous delivery." },
  { id:171, role:"Product Manager", level:"Entry Level", category:"Behavioral", difficulty:"Easy", question:"Why do you want to be a Product Manager?", hint:"Genuine answer connecting to the role. Impact, problem-solving, user empathy, cross-functional work." },
  { id:172, role:"Product Manager", level:"Entry Level", category:"Behavioral", difficulty:"Medium", question:"Tell me about a product you love and how you would improve it.", hint:"Identify a real pain point, frame it as user problem, propose solution, measure success." },
  { id:173, role:"Product Manager", level:"Entry Level", category:"Behavioral", difficulty:"Hard", question:"Describe a time you had to manage conflicting priorities. How did you decide what to work on?", hint:"Framework: impact, urgency, strategic alignment, stakeholder alignment, what you'd deprioritize." },
  { id:174, role:"Product Manager", level:"Entry Level", category:"Situational", difficulty:"Easy", question:"A key stakeholder wants a feature added to the current sprint. How do you handle this?", hint:"Assess priority, impact on current sprint, negotiate scope, be transparent about tradeoffs." },
  { id:175, role:"Product Manager", level:"Entry Level", category:"Situational", difficulty:"Medium", question:"You have limited data to make a product decision. What do you do?", hint:"Qualitative research, analogous data, small experiment, first principles, document assumptions." },
  { id:176, role:"Product Manager", level:"Entry Level", category:"Situational", difficulty:"Hard", question:"You launch a feature and metrics immediately drop. What is your process?", hint:"Don't panic, investigate (logs, funnel, segment), rollback if severe, communicate, root cause." },
  { id:177, role:"Product Manager", level:"Entry Level", category:"Culture Fit", difficulty:"Easy", question:"How do you approach working with engineers and designers?", hint:"Mutual respect, understand their constraints, include them in problem framing, don't just hand specs." },
  { id:178, role:"Product Manager", level:"Entry Level", category:"Culture Fit", difficulty:"Medium", question:"How do you handle a situation where the team disagrees with your product decision?", hint:"Listen, explain reasoning, invite challenge, own decision, remain open to being wrong." },
  { id:179, role:"Product Manager", level:"Entry Level", category:"Culture Fit", difficulty:"Hard", question:"How do you manage your own biases when making product decisions?", hint:"User research, diverse stakeholder input, pre-mortems, devil's advocate, data over intuition." },
  { id:180, role:"Product Manager", level:"Entry Level", category:"Case Study", difficulty:"Easy", question:"How would you design a feature that helps new users onboard to a complex app?", hint:"Identify key aha moment, progressive disclosure, empty states, tooltips, checklist, measure completion." },
  { id:181, role:"Product Manager", level:"Entry Level", category:"Case Study", difficulty:"Medium", question:"How would you prioritize a backlog of 50 items with no clear strategy?", hint:"RICE, MoSCoW, value vs effort matrix, align to company goals, involve stakeholders." },
  { id:182, role:"Product Manager", level:"Entry Level", category:"Case Study", difficulty:"Hard", question:"Design a product to help remote teams stay connected.", hint:"Jobs to be done, user personas, spontaneous vs structured connection, async vs sync, privacy." },

  { id:183, role:"Product Manager", level:"Mid Level", category:"Technical", difficulty:"Easy", question:"What is technical debt from a PM's perspective and how do you prioritize it?", hint:"Risk to velocity and reliability. Frame as investment, negotiate with engineering, allocate % of sprint." },
  { id:184, role:"Product Manager", level:"Mid Level", category:"Technical", difficulty:"Medium", question:"How do you write effective acceptance criteria for a complex feature?", hint:"Given/When/Then format, edge cases, performance criteria, security requirements, no ambiguity." },
  { id:185, role:"Product Manager", level:"Mid Level", category:"Technical", difficulty:"Hard", question:"How do you evaluate a build vs buy vs partner decision for a new capability?", hint:"Build: differentiation, control. Buy: speed, cost. Partner: ecosystem. TCO, core competency, time." },
  { id:186, role:"Product Manager", level:"Mid Level", category:"Behavioral", difficulty:"Easy", question:"How do you conduct user research to inform your product decisions?", hint:"Interviews, surveys, usability tests, session recordings, support tickets, data analysis." },
  { id:187, role:"Product Manager", level:"Mid Level", category:"Behavioral", difficulty:"Medium", question:"Tell me about a feature you shipped that you're most proud of. Why?", hint:"Impact, process, learning, team collaboration, data outcomes, what you'd do differently." },
  { id:188, role:"Product Manager", level:"Mid Level", category:"Behavioral", difficulty:"Hard", question:"Describe a time you had to kill a feature or project you'd invested heavily in.", hint:"Data-driven, stakeholder communication, preserve learnings, reframe as feedback, move forward." },
  { id:189, role:"Product Manager", level:"Mid Level", category:"Situational", difficulty:"Easy", question:"Engineering says a feature will take 3x longer than expected. What do you do?", hint:"Understand why, revisit scope, MVP alternative, communicate to stakeholders, reset expectations." },
  { id:190, role:"Product Manager", level:"Mid Level", category:"Situational", difficulty:"Medium", question:"You have three competing high-priority features and only enough capacity for one. How do you decide?", hint:"ROI analysis, strategic alignment, dependencies, stakeholder negotiation, document rationale." },
  { id:191, role:"Product Manager", level:"Mid Level", category:"Situational", difficulty:"Hard", question:"A competitor launches a feature you've been planning. How does this change your roadmap?", hint:"Assess actual threat, differentiation angle, accelerate or pivot, don't copy blindly." },
  { id:192, role:"Product Manager", level:"Mid Level", category:"Culture Fit", difficulty:"Easy", question:"How do you build trust with your engineering team?", hint:"Don't change requirements without notice, involve them early, shield from chaos, follow through." },
  { id:193, role:"Product Manager", level:"Mid Level", category:"Culture Fit", difficulty:"Medium", question:"How do you say no to a stakeholder request while maintaining the relationship?", hint:"Acknowledge value, explain constraints, offer alternatives, follow-up, 'not now' vs 'never'." },
  { id:194, role:"Product Manager", level:"Mid Level", category:"Culture Fit", difficulty:"Hard", question:"How do you handle a situation where sales commits features to customers that you haven't planned?", hint:"Process fix, not just fire-fighting. Align on escalation path, pre-approve list, exec alignment." },
  { id:195, role:"Product Manager", level:"Mid Level", category:"Case Study", difficulty:"Easy", question:"How would you improve the checkout flow of an e-commerce app?", hint:"Funnel analysis, drop-off points, guest checkout, autofill, trust signals, mobile optimization." },
  { id:196, role:"Product Manager", level:"Mid Level", category:"Case Study", difficulty:"Medium", question:"How would you design the metrics framework for a new feature launch?", hint:"North star, leading indicators, guardrail metrics, segmentation, instrumentation plan, baseline." },
  { id:197, role:"Product Manager", level:"Mid Level", category:"Case Study", difficulty:"Hard", question:"Design a growth strategy for a B2B SaaS product that has plateaued.", hint:"Expansion revenue, new segments, virality, integrations, pricing model, churn analysis." },

  { id:198, role:"Product Manager", level:"Senior Level", category:"Technical", difficulty:"Easy", question:"How do you engage with your engineering team during architecture discussions?", hint:"Listen, ask clarifying questions, understand constraints, translate to business impact, don't over-prescribe." },
  { id:199, role:"Product Manager", level:"Senior Level", category:"Technical", difficulty:"Medium", question:"What is event tracking and how do you design a robust instrumentation plan?", hint:"Define events taxonomy, properties, naming convention, validate, ownership, retroactive vs proactive." },
  { id:200, role:"Product Manager", level:"Senior Level", category:"Technical", difficulty:"Hard", question:"How do you approach platform vs product decisions?", hint:"Platform: horizontal enablement, API-first, internal customer. Product: end-user value. Conway's Law." },
  { id:201, role:"Product Manager", level:"Senior Level", category:"Behavioral", difficulty:"Easy", question:"How do you develop a product vision and communicate it to the team?", hint:"Start with problem, customer empathy, paint the future, connect to company strategy, narrative." },
  { id:202, role:"Product Manager", level:"Senior Level", category:"Behavioral", difficulty:"Medium", question:"How have you managed a product through a significant pivot?", hint:"Customer validation, team communication, roadmap reset, stakeholder alignment, morale management." },
  { id:203, role:"Product Manager", level:"Senior Level", category:"Behavioral", difficulty:"Hard", question:"Describe how you've developed a go-to-market strategy for a new product.", hint:"ICP, positioning, pricing, channels, launch plan, success metrics, feedback loops." },
  { id:204, role:"Product Manager", level:"Senior Level", category:"Situational", difficulty:"Easy", question:"You're taking over a product with declining engagement. What are your first 30 days?", hint:"Talk to users, review data, understand history, find quick wins, don't change too fast." },
  { id:205, role:"Product Manager", level:"Senior Level", category:"Situational", difficulty:"Medium", question:"Your product is growing fast but quality is declining. How do you balance growth vs reliability?", hint:"Reliability as product feature, SLOs, quality OKRs, technical debt allocation, user impact framing." },
  { id:206, role:"Product Manager", level:"Senior Level", category:"Situational", difficulty:"Hard", question:"You're launching in a new market. How do you adapt your product strategy?", hint:"Localization, regulatory landscape, competitive dynamics, partnership, pricing, distribution channels." },
  { id:207, role:"Product Manager", level:"Senior Level", category:"Culture Fit", difficulty:"Easy", question:"How do you create alignment across multiple stakeholder groups?", hint:"Shared goals, regular communication, involve early, make tradeoffs visible, escalation path." },
  { id:208, role:"Product Manager", level:"Senior Level", category:"Culture Fit", difficulty:"Medium", question:"How do you manage up effectively when you disagree with leadership's direction?", hint:"Raise clearly, use data, pick battles, align on goals not methods, document disagreement." },
  { id:209, role:"Product Manager", level:"Senior Level", category:"Culture Fit", difficulty:"Hard", question:"How do you build and scale a product culture across a growing organization?", hint:"Document principles, hiring for values, rituals (review cadences), reward right behaviors." },
  { id:210, role:"Product Manager", level:"Senior Level", category:"Case Study", difficulty:"Easy", question:"How would you approach a product audit for a 5-year-old SaaS platform?", hint:"Usage data, customer interviews, competitor benchmarking, feature graveyard analysis, NPS deep dive." },
  { id:211, role:"Product Manager", level:"Senior Level", category:"Case Study", difficulty:"Medium", question:"Design a self-serve onboarding experience for a B2B enterprise product.", hint:"Role-based onboarding, progressive complexity, success milestones, in-app guidance, admin vs end-user." },
  { id:212, role:"Product Manager", level:"Senior Level", category:"Case Study", difficulty:"Hard", question:"How would you design an AI-powered feature for a productivity tool? Walk me through your process.", hint:"User problem first, AI value add, data requirements, trust/transparency, failure modes, evaluation." },

  { id:213, role:"Product Manager", level:"Lead / Manager", category:"Technical", difficulty:"Easy", question:"How do you ensure technical teams have the context they need to make good decisions independently?", hint:"Clear strategy, documented principles, OKRs, regular syncs, trust and autonomy." },
  { id:214, role:"Product Manager", level:"Lead / Manager", category:"Technical", difficulty:"Medium", question:"How do you manage the technical roadmap alongside the product roadmap?", hint:"Dedicated capacity, tech debt scoring, collaborate with engineering leads, business case framing." },
  { id:215, role:"Product Manager", level:"Lead / Manager", category:"Technical", difficulty:"Hard", question:"How do you build a platform strategy that serves both internal and external developers?", hint:"API design, developer experience, versioning, docs, sandbox, feedback loops, DX vs UX tradeoffs." },
  { id:216, role:"Product Manager", level:"Lead / Manager", category:"Behavioral", difficulty:"Easy", question:"How do you develop junior PMs on your team?", hint:"Stretch assignments, shadowing, structured feedback, safe-to-fail scope, career conversations." },
  { id:217, role:"Product Manager", level:"Lead / Manager", category:"Behavioral", difficulty:"Medium", question:"How do you manage a team of PMs across different products with competing priorities?", hint:"Portfolio view, shared OKRs, resource allocation framework, dependency management, escalation." },
  { id:218, role:"Product Manager", level:"Lead / Manager", category:"Behavioral", difficulty:"Hard", question:"Tell me about a time you had to restructure your product team. How did you approach it?", hint:"Diagnose root cause, communicate early, involve team, minimize disruption, redefine ownership." },
  { id:219, role:"Product Manager", level:"Lead / Manager", category:"Situational", difficulty:"Easy", question:"Two product teams are building overlapping features. How do you resolve this?", hint:"Surface early, shared roadmap review, consolidate ownership, avoid internal competition." },
  { id:220, role:"Product Manager", level:"Lead / Manager", category:"Situational", difficulty:"Medium", question:"Your company is pivoting its core product. How do you lead your team through the change?", hint:"Transparent communication, involve team in problem, celebrate old wins, focus on customer continuity." },
  { id:221, role:"Product Manager", level:"Lead / Manager", category:"Situational", difficulty:"Hard", question:"The board wants a new product that contradicts your team's current strategy. How do you navigate?", hint:"Understand board's thesis, validate with data, present alternatives, negotiate scope, align leadership." },
  { id:222, role:"Product Manager", level:"Lead / Manager", category:"Culture Fit", difficulty:"Easy", question:"What does good product culture look like to you?", hint:"Customer obsession, data-informed, iterative, psychological safety, shared ownership, fast feedback." },
  { id:223, role:"Product Manager", level:"Lead / Manager", category:"Culture Fit", difficulty:"Medium", question:"How do you build a culture of customer empathy across the product org?", hint:"Shared access to research, CS time, customer advisory, user story mapping, celebrate customer wins." },
  { id:224, role:"Product Manager", level:"Lead / Manager", category:"Culture Fit", difficulty:"Hard", question:"How do you handle a high-performing PM who is damaging team morale?", hint:"Direct feedback on behavior, not performance. Be specific, timely, document, set expectations." },
  { id:225, role:"Product Manager", level:"Lead / Manager", category:"Case Study", difficulty:"Easy", question:"How would you define and measure product-market fit for a new B2C product?", hint:"40% rule, retention curves, organic growth, NPS + churn combination, cohort analysis." },
  { id:226, role:"Product Manager", level:"Lead / Manager", category:"Case Study", difficulty:"Medium", question:"Design a product strategy for entering a market where you're 3 years behind competitors.", hint:"Underserved segments, differentiation, speed-to-value, partnerships, pricing disruption." },
  { id:227, role:"Product Manager", level:"Lead / Manager", category:"Case Study", difficulty:"Hard", question:"How would you build a product-led growth motion for an enterprise SaaS product?", hint:"Free tier, viral features, in-product activation, expansion triggers, bottom-up and top-down motion." },

  // ═══════════════════════════════════════════════════════════
  // UX DESIGNER
  // ═══════════════════════════════════════════════════════════

  { id:228, role:"UX Designer", level:"Entry Level", category:"Technical", difficulty:"Easy", question:"What is the difference between wireframes, mockups, and prototypes?", hint:"Wireframe: structure/layout. Mockup: visual fidelity. Prototype: interactive simulation of flow." },
  { id:229, role:"UX Designer", level:"Entry Level", category:"Technical", difficulty:"Easy", question:"What is design thinking and what are its five stages?", hint:"Empathize, Define, Ideate, Prototype, Test — iterative, human-centered problem-solving process." },
  { id:230, role:"UX Designer", level:"Entry Level", category:"Technical", difficulty:"Medium", question:"What accessibility standards should a UX designer know?", hint:"WCAG 2.1 levels A/AA/AAA, contrast ratios, alt text, keyboard navigation, ARIA roles, screen reader testing." },
  { id:231, role:"UX Designer", level:"Entry Level", category:"Technical", difficulty:"Medium", question:"What is a design system and why is it valuable?", hint:"Shared components, tokens, patterns. Consistency, speed, reduced redework, single source of truth." },
  { id:232, role:"UX Designer", level:"Entry Level", category:"Technical", difficulty:"Hard", question:"Explain the principles of information architecture.", hint:"Organization, labeling, navigation, search. Card sorting, tree testing, mental models, findability." },
  { id:233, role:"UX Designer", level:"Entry Level", category:"Technical", difficulty:"Hard", question:"How do you design for different screen sizes and devices?", hint:"Responsive vs adaptive, mobile-first, breakpoints, touch targets (48px), progressive disclosure." },
  { id:234, role:"UX Designer", level:"Entry Level", category:"Behavioral", difficulty:"Easy", question:"Walk me through your design process for a recent project.", hint:"Discovery, research, ideation, prototyping, testing, iteration. Show end-to-end thinking." },
  { id:235, role:"UX Designer", level:"Entry Level", category:"Behavioral", difficulty:"Medium", question:"How do you take feedback on your designs without becoming defensive?", hint:"Separate ego from work, ask clarifying questions, distinguish opinion from user data, thank and iterate." },
  { id:236, role:"UX Designer", level:"Entry Level", category:"Behavioral", difficulty:"Hard", question:"Tell me about a design decision you made that turned out to be wrong. What did you learn?", hint:"Honest self-reflection, testing would have caught it earlier, what you'd do differently." },
  { id:237, role:"UX Designer", level:"Entry Level", category:"Situational", difficulty:"Easy", question:"A developer says your design is too complex to build in time. How do you respond?", hint:"Collaborate early, understand constraints, simplify without losing core UX value, prioritize." },
  { id:238, role:"UX Designer", level:"Entry Level", category:"Situational", difficulty:"Medium", question:"You're given a one-week deadline to design a completely new feature. How do you approach it?", hint:"Define scope, lean on existing patterns, low-fi first, quick user feedback, communicate constraints." },
  { id:239, role:"UX Designer", level:"Entry Level", category:"Situational", difficulty:"Hard", question:"Stakeholders want to add more features to an already cluttered interface. How do you push back?", hint:"User testing data, cognitive load, progressive disclosure, feature usage data, propose IA restructure." },
  { id:240, role:"UX Designer", level:"Entry Level", category:"Culture Fit", difficulty:"Easy", question:"How do you stay inspired and keep your design skills sharp?", hint:"Dribbble, Behance, conferences, books (Don Norman), design critiques, redesign challenges." },
  { id:241, role:"UX Designer", level:"Entry Level", category:"Culture Fit", difficulty:"Medium", question:"How do you handle a situation where the PM's vision conflicts with what your user research shows?", hint:"Present data clearly, facilitate empathy for users, propose testing the hypothesis, document." },
  { id:242, role:"UX Designer", level:"Entry Level", category:"Culture Fit", difficulty:"Hard", question:"How do you approach designing for an audience you're not personally familiar with?", hint:"Immersive research, diverse participant recruitment, avoid assumption, domain expert interviews." },
  { id:243, role:"UX Designer", level:"Entry Level", category:"Case Study", difficulty:"Easy", question:"Redesign the onboarding flow of an app you use regularly.", hint:"Current pain points, user goals at onboarding, progressive steps, reduce friction, measure completion." },
  { id:244, role:"UX Designer", level:"Entry Level", category:"Case Study", difficulty:"Medium", question:"How would you design a search experience for a large e-commerce platform?", hint:"Autocomplete, filters, empty states, no-results handling, search intent, relevance ranking UI." },
  { id:245, role:"UX Designer", level:"Entry Level", category:"Case Study", difficulty:"Hard", question:"Design a dashboard for a first-time small business owner.", hint:"User research on mental models, key metrics, progressive complexity, mobile vs desktop, customization." },

  { id:246, role:"UX Designer", level:"Mid Level", category:"Technical", difficulty:"Easy", question:"What tools do you use for prototyping and why?", hint:"Figma, Framer, Protopie, Adobe XD. Trade-offs: fidelity, collaboration, handoff, animation." },
  { id:247, role:"UX Designer", level:"Mid Level", category:"Technical", difficulty:"Medium", question:"What is design thinking and how do you apply it on a fast-paced product team?", hint:"Adapted for speed: assumption mapping, guerrilla testing, time-boxed ideation, lean UX." },
  { id:248, role:"UX Designer", level:"Mid Level", category:"Technical", difficulty:"Hard", question:"How do you measure the success of a UX design?", hint:"Task completion rate, error rate, time on task, SUS score, NPS, conversion, qualitative themes." },
  { id:249, role:"UX Designer", level:"Mid Level", category:"Behavioral", difficulty:"Easy", question:"How do you collaborate with product managers and engineers?", hint:"Involve them in research, design in public, handoff specs, be present in sprint ceremonies." },
  { id:250, role:"UX Designer", level:"Mid Level", category:"Behavioral", difficulty:"Medium", question:"Tell me about a complex user problem you solved. What was your process?", hint:"Research, synthesis, reframe, ideation, iteration, validation, impact." },
  { id:251, role:"UX Designer", level:"Mid Level", category:"Behavioral", difficulty:"Hard", question:"Describe a project where you had to balance business goals and user needs that were in tension.", hint:"Transparent tradeoff discussion, user advocacy, quantify impact both ways, negotiate." },
  { id:252, role:"UX Designer", level:"Mid Level", category:"Situational", difficulty:"Easy", question:"You join a team that doesn't currently do user research. How do you change this?", hint:"Start small, quick wins, show value, connect research to outcomes, lightweight methods first." },
  { id:253, role:"UX Designer", level:"Mid Level", category:"Situational", difficulty:"Medium", question:"You're designing a feature for two very different user personas. How do you handle this?", hint:"Adaptive UI, role-based defaults, shared patterns where possible, user testing with both groups." },
  { id:254, role:"UX Designer", level:"Mid Level", category:"Situational", difficulty:"Hard", question:"Your usability testing shows major issues with a design the team already loves. What do you do?", hint:"Present data clearly, show clips if possible, depersonalize from team's effort, propose iterations." },
  { id:255, role:"UX Designer", level:"Mid Level", category:"Culture Fit", difficulty:"Easy", question:"How do you advocate for the user when business priorities take over?", hint:"User data, cost of poor UX (support tickets, churn), frame as business risk not just ethics." },
  { id:256, role:"UX Designer", level:"Mid Level", category:"Culture Fit", difficulty:"Medium", question:"Describe your ideal design process within an agile team.", hint:"Discovery in parallel with delivery, design sprint, collaborative story mapping, design debt tracking." },
  { id:257, role:"UX Designer", level:"Mid Level", category:"Culture Fit", difficulty:"Hard", question:"How do you contribute to a design system and keep it healthy?", hint:"Document contributions, deprecation process, governance model, adoption tracking, communication." },
  { id:258, role:"UX Designer", level:"Mid Level", category:"Case Study", difficulty:"Easy", question:"How would you improve the mobile navigation of a news app with 50+ sections?", hint:"Usage data, card sorting, progressive disclosure, bottom nav limits, search, personalization." },
  { id:259, role:"UX Designer", level:"Mid Level", category:"Case Study", difficulty:"Medium", question:"Design an empty state experience for a new user in a task management app.", hint:"Educate + invite action, don't leave blank, template suggestions, celebrate first completion." },
  { id:260, role:"UX Designer", level:"Mid Level", category:"Case Study", difficulty:"Hard", question:"How would you approach a full redesign of a legacy enterprise application?", hint:"Shadow sessions, JTBD, pilot with willing users, dark launch, migration path, feedback loops." },

  { id:261, role:"UX Designer", level:"Senior Level", category:"Technical", difficulty:"Easy", question:"How do you create and maintain component documentation for a design system?", hint:"Usage guidelines, do/don't examples, prop definitions, versioning, Storybook integration." },
  { id:262, role:"UX Designer", level:"Senior Level", category:"Technical", difficulty:"Medium", question:"How do you design for performance? What UX considerations affect load times?", hint:"Skeleton screens, progressive loading, perceived performance, lazy load, avoid jank, critical path." },
  { id:263, role:"UX Designer", level:"Senior Level", category:"Technical", difficulty:"Hard", question:"How do you approach designing AI-powered features? What unique UX challenges arise?", hint:"Uncertainty UI, confidence indicators, error recovery, explainability, user control, trust calibration." },
  { id:264, role:"UX Designer", level:"Senior Level", category:"Behavioral", difficulty:"Easy", question:"How do you approach mentoring junior designers?", hint:"Portfolio reviews, design critiques, stretch projects, process guidance, psychological safety." },
  { id:265, role:"UX Designer", level:"Senior Level", category:"Behavioral", difficulty:"Medium", question:"How have you contributed to building or scaling a design system?", hint:"Component audit, token system, governance, adoption strategy, documentation, cross-team coordination." },
  { id:266, role:"UX Designer", level:"Senior Level", category:"Behavioral", difficulty:"Hard", question:"Tell me about a time you drove a major product direction change based on user research.", hint:"Research findings, stakeholder persuasion, risk framing, outcome, what you'd do differently." },
  { id:267, role:"UX Designer", level:"Senior Level", category:"Situational", difficulty:"Easy", question:"You're asked to design for a global product with users in 15 countries. What's your approach?", hint:"Localization vs globalization, cultural research, RTL languages, date/number formats, color meaning." },
  { id:268, role:"UX Designer", level:"Senior Level", category:"Situational", difficulty:"Medium", question:"Your design is technically correct but users in testing consistently fail a key task. What do you do?", hint:"Accept the data, don't rationalize failure, identify mental model gap, redesign the affordance." },
  { id:269, role:"UX Designer", level:"Senior Level", category:"Situational", difficulty:"Hard", question:"You're brought in to fix a product that has received consistently poor UX reviews. Where do you start?", hint:"Heuristic eval, user research, analytics, benchmark current state, systemic vs surface issues." },
  { id:270, role:"UX Designer", level:"Senior Level", category:"Culture Fit", difficulty:"Easy", question:"How do you build credibility with engineers and product managers as a UX designer?", hint:"Deliver on time, understand constraints, explain design rationale with data, be collaborative." },
  { id:271, role:"UX Designer", level:"Senior Level", category:"Culture Fit", difficulty:"Medium", question:"How do you create a design-first culture in an organization that doesn't prioritize UX?", hint:"Show ROI of design, quick wins, executive sponsorship, embed in teams, celebrate UX outcomes." },
  { id:272, role:"UX Designer", level:"Senior Level", category:"Culture Fit", difficulty:"Hard", question:"How do you handle situations where you believe a product direction is ethically problematic from a UX perspective?", hint:"Dark patterns, manipulation. Raise concerns with evidence, propose ethical alternatives, escalate." },
  { id:273, role:"UX Designer", level:"Senior Level", category:"Case Study", difficulty:"Easy", question:"How would you design the UX for a voice-first interface on a smart speaker?", hint:"No visual affordances, confirmation patterns, error recovery, progressive disclosure, latency feedback." },
  { id:274, role:"UX Designer", level:"Senior Level", category:"Case Study", difficulty:"Medium", question:"Design a notification system that respects user attention and avoids notification fatigue.", hint:"Frequency capping, priority tiers, user preferences, batching, delivery timing, opt-out paths." },
  { id:275, role:"UX Designer", level:"Senior Level", category:"Case Study", difficulty:"Hard", question:"How would you redesign the checkout experience of a major airline booking system?", hint:"Fare complexity, upsell pressure vs trust, seat selection, confirmation anxiety, error recovery." },

  { id:276, role:"UX Designer", level:"Lead / Manager", category:"Technical", difficulty:"Easy", question:"How do you ensure design quality across a team of multiple designers?", hint:"Shared critique sessions, design system adoption, quality rubrics, design reviews before handoff." },
  { id:277, role:"UX Designer", level:"Lead / Manager", category:"Technical", difficulty:"Medium", question:"How do you balance standardization in a design system with the need for product-specific flexibility?", hint:"Token system, variant strategy, contribution model, governance, customization zones." },
  { id:278, role:"UX Designer", level:"Lead / Manager", category:"Technical", difficulty:"Hard", question:"How do you architect a research operations function within a design organization?", hint:"Research library, participant recruitment, tool stack, democratizing research, insight management." },
  { id:279, role:"UX Designer", level:"Lead / Manager", category:"Behavioral", difficulty:"Easy", question:"How do you hire and build a design team?", hint:"Portfolio review process, culture addition vs fit, diverse background, practical exercise, values." },
  { id:280, role:"UX Designer", level:"Lead / Manager", category:"Behavioral", difficulty:"Medium", question:"How do you manage creative differences within a design team?", hint:"Design principles as anchor, critique culture, data to break ties, celebrate multiple valid solutions." },
  { id:281, role:"UX Designer", level:"Lead / Manager", category:"Behavioral", difficulty:"Hard", question:"How have you elevated the strategic role of design in an organization?", hint:"Business metrics framing, executive relationships, seat at the table, design strategy docs, C-suite." },
  { id:282, role:"UX Designer", level:"Lead / Manager", category:"Situational", difficulty:"Easy", question:"Your design team is stretched too thin across too many projects. How do you handle this?", hint:"Prioritization framework, negotiate with PM/leadership, tiered design support, self-service tools." },
  { id:283, role:"UX Designer", level:"Lead / Manager", category:"Situational", difficulty:"Medium", question:"A senior designer on your team is resistant to adopting the new design system. How do you approach this?", hint:"Listen to concerns, involve them in evolution, make migration easy, address legitimate pain points." },
  { id:284, role:"UX Designer", level:"Lead / Manager", category:"Situational", difficulty:"Hard", question:"You're asked to justify the ROI of investing in a full UX research function. How do you make the case?", hint:"Cost of poor decisions, dev rework avoided, NPS/conversion impact, competitive differentiation." },
  { id:285, role:"UX Designer", level:"Lead / Manager", category:"Culture Fit", difficulty:"Easy", question:"What does a healthy design culture look like to you?", hint:"Psychological safety, critique norms, research-informed, cross-functional respect, growth mindset." },
  { id:286, role:"UX Designer", level:"Lead / Manager", category:"Culture Fit", difficulty:"Medium", question:"How do you help non-designers understand and appreciate the value of UX?", hint:"Involve them in research, share user stories, connect to business outcomes, design literacy workshops." },
  { id:287, role:"UX Designer", level:"Lead / Manager", category:"Culture Fit", difficulty:"Hard", question:"How do you balance the creative autonomy of designers with consistent product quality?", hint:"Shared principles not rules, design leadership as guardrails, trust + review cadence." },
  { id:288, role:"UX Designer", level:"Lead / Manager", category:"Case Study", difficulty:"Easy", question:"How would you structure a design review process for a 10-person design team?", hint:"Critique stages (concept, mid-fi, final), attendance, asynchronous option, actionable output." },
  { id:289, role:"UX Designer", level:"Lead / Manager", category:"Case Study", difficulty:"Medium", question:"Design a UX strategy for a company launching its first mobile app.", hint:"Platform conventions, native vs web, feature prioritization for v1, research plan, success metrics." },
  { id:290, role:"UX Designer", level:"Lead / Manager", category:"Case Study", difficulty:"Hard", question:"How would you build the research and design process for a company expanding into an emerging market?", hint:"On-ground research, connectivity constraints, cultural adaptation, local testing, feedback loops." },

  // ═══════════════════════════════════════════════════════════
  // DEVOPS ENGINEER
  // ═══════════════════════════════════════════════════════════

  { id:291, role:"DevOps Engineer", level:"Entry Level", category:"Technical", difficulty:"Easy", question:"What is DNS and how does it work?", hint:"Domain → IP. Recursive vs authoritative resolvers. TTL, caching, A/CNAME/MX records." },
  { id:292, role:"DevOps Engineer", level:"Entry Level", category:"Technical", difficulty:"Easy", question:"What is CI/CD and why is it important?", hint:"Continuous Integration: merge and test frequently. CD: automated deploy. Reduces risk, faster feedback." },
  { id:293, role:"DevOps Engineer", level:"Entry Level", category:"Technical", difficulty:"Medium", question:"What is Docker and how does containerization differ from virtualization?", hint:"Containers: share OS kernel, lightweight. VMs: full OS per instance, heavier. Docker layered images." },
  { id:294, role:"DevOps Engineer", level:"Entry Level", category:"Technical", difficulty:"Medium", question:"Explain the difference between horizontal and vertical scaling.", hint:"Vertical: bigger machine (CPU/RAM). Horizontal: more instances. H-scaling preferred for resilience." },
  { id:295, role:"DevOps Engineer", level:"Entry Level", category:"Technical", difficulty:"Hard", question:"What is Kubernetes and why is it used?", hint:"Container orchestration: scheduling, scaling, self-healing, service discovery, rolling updates." },
  { id:296, role:"DevOps Engineer", level:"Entry Level", category:"Technical", difficulty:"Hard", question:"Explain how a load balancer works and the difference between L4 and L7 load balancing.", hint:"L4: TCP/UDP routing. L7: HTTP-aware, path/header routing. Health checks, sticky sessions." },
  { id:297, role:"DevOps Engineer", level:"Entry Level", category:"Behavioral", difficulty:"Easy", question:"Tell me about a time you broke something in production. How did you handle it?", hint:"Immediate mitigation, transparent communication, root cause analysis, preventive measures added." },
  { id:298, role:"DevOps Engineer", level:"Entry Level", category:"Behavioral", difficulty:"Medium", question:"How do you approach learning a new infrastructure tool or platform?", hint:"Official docs, hands-on lab, tutorials, small proof of concept, community forums." },
  { id:299, role:"DevOps Engineer", level:"Entry Level", category:"Behavioral", difficulty:"Hard", question:"Describe a time you had to troubleshoot an issue you'd never seen before.", hint:"Systematic isolation, logs/metrics/traces, rubber duck, docs, ask senior, blameless process." },
  { id:300, role:"DevOps Engineer", level:"Entry Level", category:"Situational", difficulty:"Easy", question:"You notice a service is using 90% CPU. What do you do?", hint:"Check metrics, identify process, look for infinite loop/memory leak, scale or restart, alert team." },
  { id:301, role:"DevOps Engineer", level:"Entry Level", category:"Situational", difficulty:"Medium", question:"A deployment fails halfway through. How do you respond?", hint:"Rollback first, preserve logs, communicate status, investigate safely, don't re-deploy blindly." },
  { id:302, role:"DevOps Engineer", level:"Entry Level", category:"Situational", difficulty:"Hard", question:"A developer asks you to give them full prod database access. How do you handle it?", hint:"Principle of least privilege. Understand need, temporary scoped access, audit log, reject full access." },
  { id:303, role:"DevOps Engineer", level:"Entry Level", category:"Culture Fit", difficulty:"Easy", question:"What does 'infrastructure as code' mean to you and why does it matter?", hint:"Reproducibility, version control, peer review, automated provisioning, disaster recovery." },
  { id:304, role:"DevOps Engineer", level:"Entry Level", category:"Culture Fit", difficulty:"Medium", question:"How do you approach on-call responsibilities?", hint:"Runbooks, escalation paths, blameless culture, post-mortems, rotating fairly, avoid alert fatigue." },
  { id:305, role:"DevOps Engineer", level:"Entry Level", category:"Culture Fit", difficulty:"Hard", question:"How do you balance developer velocity with system stability?", hint:"Feature flags, canary deployments, automated tests, SLOs, error budgets." },
  { id:306, role:"DevOps Engineer", level:"Entry Level", category:"Case Study", difficulty:"Easy", question:"Design a basic CI pipeline for a web application.", hint:"Source → build → test → lint → artifact → notify. Tools: GitHub Actions, Jenkins. Fail fast." },
  { id:307, role:"DevOps Engineer", level:"Entry Level", category:"Case Study", difficulty:"Medium", question:"How would you set up centralized logging for a 10-service application?", hint:"ELK or Grafana Loki, structured JSON logs, correlation IDs, retention policy, alerting on errors." },
  { id:308, role:"DevOps Engineer", level:"Entry Level", category:"Case Study", difficulty:"Hard", question:"Design a zero-downtime deployment strategy for a stateful application.", hint:"Blue-green, canary, rolling update. Database migration strategy critical. Health checks, traffic cutover." },

  { id:309, role:"DevOps Engineer", level:"Mid Level", category:"Technical", difficulty:"Easy", question:"What is Terraform and how does it differ from Ansible?", hint:"Terraform: declarative infrastructure provisioning. Ansible: imperative configuration management." },
  { id:310, role:"DevOps Engineer", level:"Mid Level", category:"Technical", difficulty:"Medium", question:"Explain Kubernetes pod lifecycle and how health probes work.", hint:"Pending → Running → Succeeded/Failed. Liveness (restart), Readiness (traffic), Startup probes." },
  { id:311, role:"DevOps Engineer", level:"Mid Level", category:"Technical", difficulty:"Medium", question:"What is a service mesh and when would you use one?", hint:"Istio, Linkerd. mTLS, observability, traffic management, circuit breaking. Useful in complex microservices." },
  { id:312, role:"DevOps Engineer", level:"Mid Level", category:"Technical", difficulty:"Hard", question:"How do you design a secrets management strategy for a cloud-native application?", hint:"Vault, AWS Secrets Manager, no secrets in code, rotation, encryption at rest and transit." },
  { id:313, role:"DevOps Engineer", level:"Mid Level", category:"Technical", difficulty:"Hard", question:"What is GitOps and how does it improve deployment workflows?", hint:"Git as source of truth, ArgoCD/Flux, pull-based deployments, audit trail, drift detection." },
  { id:314, role:"DevOps Engineer", level:"Mid Level", category:"Behavioral", difficulty:"Easy", question:"How do you document runbooks and incident response procedures?", hint:"Clear steps, decision trees, contact escalation, link to dashboards, test regularly, version control." },
  { id:315, role:"DevOps Engineer", level:"Mid Level", category:"Behavioral", difficulty:"Medium", question:"Tell me about a significant outage you were part of resolving. Walk me through it.", hint:"Timeline, detection, mitigation, root cause, communication, post-mortem, prevention." },
  { id:316, role:"DevOps Engineer", level:"Mid Level", category:"Behavioral", difficulty:"Hard", question:"How have you improved developer experience for your engineering team?", hint:"Self-service pipelines, better local dev environments, faster CI, good error messages, docs." },
  { id:317, role:"DevOps Engineer", level:"Mid Level", category:"Situational", difficulty:"Easy", question:"Your monitoring shows increased 5xx errors from one microservice. What do you do?", hint:"Check logs, recent deployments, downstream dependencies, scale if needed, page on-call engineer." },
  { id:318, role:"DevOps Engineer", level:"Mid Level", category:"Situational", difficulty:"Medium", question:"You need to migrate a monolith to containers without disrupting production. How do you plan this?", hint:"Containerize first without behavior change, test parity, gradual traffic migration, rollback plan." },
  { id:319, role:"DevOps Engineer", level:"Mid Level", category:"Situational", difficulty:"Hard", question:"Your Kubernetes cluster is running out of capacity during peak hours. How do you address this?", hint:"HPA, cluster autoscaler, spot/preemptible nodes, resource requests/limits audit, rightsizing." },
  { id:320, role:"DevOps Engineer", level:"Mid Level", category:"Culture Fit", difficulty:"Easy", question:"How do you approach building a DevOps culture with developers who are resistant to change?", hint:"Show not tell, quick wins, involve them in decisions, reduce their pain points first." },
  { id:321, role:"DevOps Engineer", level:"Mid Level", category:"Culture Fit", difficulty:"Medium", question:"How do you balance speed of delivery with maintaining a secure and stable platform?", hint:"Automated testing, SAST, feature flags, SLOs, error budgets, shift-left security." },
  { id:322, role:"DevOps Engineer", level:"Mid Level", category:"Culture Fit", difficulty:"Hard", question:"How do you drive adoption of infrastructure best practices across multiple development teams?", hint:"Platform team model, paved roads, templates, inner source, champions, enablement not mandates." },
  { id:323, role:"DevOps Engineer", level:"Mid Level", category:"Case Study", difficulty:"Easy", question:"How would you set up a monitoring and alerting stack for a production application?", hint:"Prometheus + Grafana or Datadog. SLIs, SLOs, error rates, latency, saturation, alerting on burn rate." },
  { id:324, role:"DevOps Engineer", level:"Mid Level", category:"Case Study", difficulty:"Medium", question:"Design a multi-environment deployment strategy for a SaaS product.", hint:"Dev/staging/prod, environment parity, environment-specific configs, promotion gates, infra as code." },
  { id:325, role:"DevOps Engineer", level:"Mid Level", category:"Case Study", difficulty:"Hard", question:"How would you implement a disaster recovery strategy for a critical service?", hint:"RTO/RPO definition, active-passive vs active-active, data replication, failover automation, DR drills." },

  { id:326, role:"DevOps Engineer", level:"Senior Level", category:"Technical", difficulty:"Easy", question:"What is eBPF and what are its applications in observability and security?", hint:"Kernel-level programmability, zero-copy networking, runtime security, low-overhead tracing tools." },
  { id:327, role:"DevOps Engineer", level:"Senior Level", category:"Technical", difficulty:"Medium", question:"How do you implement cost optimization in a cloud environment?", hint:"Right-sizing, reserved/spot instances, auto-scaling, storage tiering, unused resource cleanup, FinOps." },
  { id:328, role:"DevOps Engineer", level:"Senior Level", category:"Technical", difficulty:"Hard", question:"How do you implement multi-region disaster recovery for a global SaaS application?", hint:"Active-active vs active-passive, data replication lag, DNS failover, consistency tradeoffs, chaos testing." },
  { id:329, role:"DevOps Engineer", level:"Senior Level", category:"Behavioral", difficulty:"Easy", question:"How do you approach building a platform team that serves multiple engineering teams?", hint:"Internal customer mindset, SLAs for the platform, self-service, docs, feedback loops." },
  { id:330, role:"DevOps Engineer", level:"Senior Level", category:"Behavioral", difficulty:"Medium", question:"How have you built and maintained a security-first DevOps practice?", hint:"Shift-left, SAST/DAST, secrets scanning, dependency audits, access reviews, threat modeling." },
  { id:331, role:"DevOps Engineer", level:"Senior Level", category:"Behavioral", difficulty:"Hard", question:"Tell me about the most complex infrastructure architecture you've designed. Walk me through your decisions.", hint:"Requirements, constraints, trade-offs, what you'd change now, key learnings." },
  { id:332, role:"DevOps Engineer", level:"Senior Level", category:"Situational", difficulty:"Easy", question:"The engineering team wants to adopt a new cloud service you're unfamiliar with. How do you evaluate it?", hint:"Security review, cost model, vendor lock-in, operational burden, maturity, internal expertise." },
  { id:333, role:"DevOps Engineer", level:"Senior Level", category:"Situational", difficulty:"Medium", question:"You discover a critical security vulnerability in your production infrastructure. What do you do?", hint:"Severity assessment, immediate mitigation, restrict access, notify security team, patch, post-mortem." },
  { id:334, role:"DevOps Engineer", level:"Senior Level", category:"Situational", difficulty:"Hard", question:"You're tasked with reducing infrastructure costs by 40% without degrading performance. How do you start?", hint:"Audit spend, categorize, quick wins first, architectural changes, reserved capacity, waste elimination." },
  { id:335, role:"DevOps Engineer", level:"Senior Level", category:"Culture Fit", difficulty:"Easy", question:"What does a mature SRE/DevOps practice look like to you?", hint:"Error budgets, blameless post-mortems, automation-first, self-service, measurable SLOs." },
  { id:336, role:"DevOps Engineer", level:"Senior Level", category:"Culture Fit", difficulty:"Medium", question:"How do you evangelize DevOps principles to engineering leadership?", hint:"Business metrics (DORA), case studies, pilot team wins, connect to developer happiness and retention." },
  { id:337, role:"DevOps Engineer", level:"Senior Level", category:"Culture Fit", difficulty:"Hard", question:"How do you handle conflicting priorities between platform reliability and feature delivery speed?", hint:"Error budgets, SLO negotiation, data-driven conversation, align at exec level." },
  { id:338, role:"DevOps Engineer", level:"Senior Level", category:"Case Study", difficulty:"Easy", question:"How would you design the observability stack for a microservices platform?", hint:"Three pillars: metrics, logs, traces. OpenTelemetry, Prometheus, Jaeger/Tempo, correlation IDs." },
  { id:339, role:"DevOps Engineer", level:"Senior Level", category:"Case Study", difficulty:"Medium", question:"Design a Kubernetes-based deployment architecture for a high-traffic e-commerce application.", hint:"HPA, cluster autoscaler, PDBs, resource quotas, multi-AZ, ingress controller, security policies." },
  { id:340, role:"DevOps Engineer", level:"Senior Level", category:"Case Study", difficulty:"Hard", question:"How would you architect a zero-trust network model for a cloud-native enterprise application?", hint:"Identity-based access, mTLS, service mesh, micro-segmentation, SPIFFE/SPIRE, no implicit trust." },

  { id:341, role:"DevOps Engineer", level:"Lead / Manager", category:"Technical", difficulty:"Easy", question:"How do you define and measure platform reliability targets?", hint:"SLIs, SLOs, error budgets, DORA metrics (lead time, deploy freq, MTTR, change fail rate)." },
  { id:342, role:"DevOps Engineer", level:"Lead / Manager", category:"Technical", difficulty:"Medium", question:"How do you evaluate and select cloud vendors for an enterprise?", hint:"TCO, lock-in risk, compliance, support SLAs, migration cost, strategic partnerships, multi-cloud." },
  { id:343, role:"DevOps Engineer", level:"Lead / Manager", category:"Technical", difficulty:"Hard", question:"How do you architect a FinOps discipline into your engineering organization?", hint:"Cloud cost ownership model, tagging strategy, showback/chargeback, optimization champions, tooling." },
  { id:344, role:"DevOps Engineer", level:"Lead / Manager", category:"Behavioral", difficulty:"Easy", question:"How do you build and grow a DevOps/SRE team?", hint:"Hire for curiosity and SWE skills, blend of backgrounds, clear career ladders, on-call fairness." },
  { id:345, role:"DevOps Engineer", level:"Lead / Manager", category:"Behavioral", difficulty:"Medium", question:"How do you manage on-call burnout on your infrastructure team?", hint:"Rotation fairness, alert quality (reduce noise), runbooks, psychological safety, compensate properly." },
  { id:346, role:"DevOps Engineer", level:"Lead / Manager", category:"Behavioral", difficulty:"Hard", question:"Describe how you've led a major platform migration (cloud, Kubernetes, etc.) across an organization.", hint:"Stakeholder alignment, migration playbook, pilot teams, risk gates, communication, rollback plan." },
  { id:347, role:"DevOps Engineer", level:"Lead / Manager", category:"Situational", difficulty:"Easy", question:"Two development teams have conflicting infrastructure requirements. How do you resolve this?", hint:"Understand constraints, propose shared solution, escalate if needed, document decision." },
  { id:348, role:"DevOps Engineer", level:"Lead / Manager", category:"Situational", difficulty:"Medium", question:"Leadership wants to reduce infrastructure headcount by 30%. How do you respond?", hint:"Quantify value, show automation ROI, risk analysis, propose optimization roadmap, don't just accept." },
  { id:349, role:"DevOps Engineer", level:"Lead / Manager", category:"Situational", difficulty:"Hard", question:"Your platform is causing frequent developer frustration due to flaky pipelines. How do you fix this systematically?", hint:"Measure flakiness rate, categorize causes, dedicate fix-it sprints, reliability SLA for platform." },
  { id:350, role:"DevOps Engineer", level:"Lead / Manager", category:"Culture Fit", difficulty:"Easy", question:"What is your approach to blameless post-mortems?", hint:"Focus on systems not people, timeline-based, 5-whys, action items with owners, share broadly." },
  { id:351, role:"DevOps Engineer", level:"Lead / Manager", category:"Culture Fit", difficulty:"Medium", question:"How do you build a security culture across engineering and DevOps teams?", hint:"Security champions, shift-left tooling, training, threat modeling in design phase, celebrate good catches." },
  { id:352, role:"DevOps Engineer", level:"Lead / Manager", category:"Culture Fit", difficulty:"Hard", question:"How do you balance innovation in your platform with the need for stability for your customers?", hint:"Innovation quarters, sandboxed environments, feedback loops, risk-tiered experimentation." },
  { id:353, role:"DevOps Engineer", level:"Lead / Manager", category:"Case Study", difficulty:"Easy", question:"Design an incident management process for a 24/7 SaaS platform.", hint:"Severity tiers, on-call rotation, escalation tree, communication templates, post-mortem process." },
  { id:354, role:"DevOps Engineer", level:"Lead / Manager", category:"Case Study", difficulty:"Medium", question:"How would you build a self-service infrastructure platform for 20 engineering teams?", hint:"Golden paths, Backstage/platform portal, templated pipelines, guardrails, docs-as-code, RBAC." },
  { id:355, role:"DevOps Engineer", level:"Lead / Manager", category:"Case Study", difficulty:"Hard", question:"Design the cloud strategy for a company moving from on-premise to cloud over 3 years.", hint:"Lift-and-shift vs re-architect, phased migration, network topology, identity federation, training plan." },

  // ═══════════════════════════════════════════════════════════
  // DATA ANALYST
  // ═══════════════════════════════════════════════════════════

  { id:356, role:"Data Analyst", level:"Entry Level", category:"Technical", difficulty:"Easy", question:"What is a pivot table and when do you use it?", hint:"Summarize, aggregate, cross-tabulate. Excel/Google Sheets. Good for quick group-by summaries." },
  { id:357, role:"Data Analyst", level:"Entry Level", category:"Technical", difficulty:"Easy", question:"What is the difference between INNER JOIN, LEFT JOIN, and FULL JOIN in SQL?", hint:"Inner: matching rows only. Left: all left + matches. Full: all rows from both, nulls where no match." },
  { id:358, role:"Data Analyst", level:"Entry Level", category:"Technical", difficulty:"Medium", question:"What are window functions in SQL? Give an example.", hint:"ROW_NUMBER, RANK, LAG, LEAD, SUM OVER PARTITION. Compute over a sliding window without collapsing." },
  { id:359, role:"Data Analyst", level:"Entry Level", category:"Technical", difficulty:"Medium", question:"What is data normalization and why is it important?", hint:"Reducing redundancy, 1NF/2NF/3NF. Trade-offs between normalization and query performance." },
  { id:360, role:"Data Analyst", level:"Entry Level", category:"Technical", difficulty:"Hard", question:"How would you detect and handle outliers in a dataset?", hint:"Z-score, IQR method, visualization (box plot), domain knowledge, flag don't always delete." },
  { id:361, role:"Data Analyst", level:"Entry Level", category:"Technical", difficulty:"Hard", question:"What is cohort analysis and when would you use it?", hint:"Group users by shared trait (signup date). Track behavior over time. Retention, LTV, churn." },
  { id:362, role:"Data Analyst", level:"Entry Level", category:"Behavioral", difficulty:"Easy", question:"Walk me through a data analysis project you completed. What was your approach?", hint:"Problem, data sources, cleaning, analysis, visualization, insight, recommendation, impact." },
  { id:363, role:"Data Analyst", level:"Entry Level", category:"Behavioral", difficulty:"Medium", question:"How do you present data insights to stakeholders who aren't comfortable with numbers?", hint:"Tell a story, lead with insight not data, visuals, avoid jargon, tie to business outcome." },
  { id:364, role:"Data Analyst", level:"Entry Level", category:"Behavioral", difficulty:"Hard", question:"Describe a time your analysis changed a business decision.", hint:"Context, finding, how you communicated it, decision that changed, outcome measured." },
  { id:365, role:"Data Analyst", level:"Entry Level", category:"Situational", difficulty:"Easy", question:"You're given a dataset you've never seen before. What are your first steps?", hint:"Profile it (shape, types, nulls, distributions), understand business context, ask questions." },
  { id:366, role:"Data Analyst", level:"Entry Level", category:"Situational", difficulty:"Medium", question:"Stakeholders ask for a dashboard for everything. How do you focus them?", hint:"Identify key decisions, North Star metric, audience-specific views, start minimal and expand." },
  { id:367, role:"Data Analyst", level:"Entry Level", category:"Situational", difficulty:"Hard", question:"The numbers in your report don't match what another team is reporting. What do you do?", hint:"Don't publish conflicting reports, align on definition, trace to source, document lineage." },
  { id:368, role:"Data Analyst", level:"Entry Level", category:"Culture Fit", difficulty:"Easy", question:"How do you ensure the data you're working with is trustworthy?", hint:"Source validation, row counts, nulls check, cross-reference with known benchmarks, document assumptions." },
  { id:369, role:"Data Analyst", level:"Entry Level", category:"Culture Fit", difficulty:"Medium", question:"How do you handle pressure to find insights that support a predetermined conclusion?", hint:"Integrity is non-negotiable. Present findings honestly, show what data does and doesn't support." },
  { id:370, role:"Data Analyst", level:"Entry Level", category:"Culture Fit", difficulty:"Hard", question:"How do you balance speed and accuracy when delivering analysis under a deadline?", hint:"Scope down the question, confidence intervals, flag limitations, deliver MVP insight then iterate." },
  { id:371, role:"Data Analyst", level:"Entry Level", category:"Case Study", difficulty:"Easy", question:"How would you analyze the performance of a marketing email campaign?", hint:"Open rate, CTR, conversion, revenue per email, unsubscribes, A/B test analysis, cohort comparison." },
  { id:372, role:"Data Analyst", level:"Entry Level", category:"Case Study", difficulty:"Medium", question:"How would you build a sales funnel analysis for an e-commerce site?", hint:"Sessions → PDP views → cart adds → checkout → purchase. Drop-off rates, segment by channel." },
  { id:373, role:"Data Analyst", level:"Entry Level", category:"Case Study", difficulty:"Hard", question:"Design a churn analysis for a subscription product. What metrics would you track?", hint:"Churn rate, cohort retention curves, churn predictors, segment differences, leading indicators." },

  { id:374, role:"Data Analyst", level:"Mid Level", category:"Technical", difficulty:"Easy", question:"What is the difference between OLTP and OLAP databases?", hint:"OLTP: transactional, row-oriented, normalized. OLAP: analytical, columnar, denormalized, aggregations." },
  { id:375, role:"Data Analyst", level:"Mid Level", category:"Technical", difficulty:"Medium", question:"What is a star schema and how does it differ from a snowflake schema?", hint:"Star: fact table + flat dims, simpler queries. Snowflake: normalized dims, more joins, less storage." },
  { id:376, role:"Data Analyst", level:"Mid Level", category:"Technical", difficulty:"Medium", question:"How do you build and maintain a reliable analytics data pipeline?", hint:"Idempotency, data quality checks, monitoring, lineage, documentation, version control, alerting." },
  { id:377, role:"Data Analyst", level:"Mid Level", category:"Technical", difficulty:"Hard", question:"How would you design a metrics layer for a mid-sized company?", hint:"dbt metrics, semantic layer, single source of truth, governance, documentation, self-service." },
  { id:378, role:"Data Analyst", level:"Mid Level", category:"Technical", difficulty:"Hard", question:"What is A/B testing and what statistical considerations are critical?", hint:"Randomization, sample size/power, significance level, multiple testing correction, novelty effect." },
  { id:379, role:"Data Analyst", level:"Mid Level", category:"Behavioral", difficulty:"Easy", question:"How do you prioritize analytical requests when you're overloaded?", hint:"Impact, urgency, strategic alignment, effort, negotiate deadlines, delegate exploratory." },
  { id:380, role:"Data Analyst", level:"Mid Level", category:"Behavioral", difficulty:"Medium", question:"Tell me about a time you identified a data quality issue that had downstream business impact.", hint:"How you found it, business impact quantified, root cause, fix, prevention process." },
  { id:381, role:"Data Analyst", level:"Mid Level", category:"Behavioral", difficulty:"Hard", question:"Describe a time you built a self-service analytics capability that empowered non-technical users.", hint:"Tool choice, training, documentation, adoption strategy, feedback loops, ongoing support." },
  { id:382, role:"Data Analyst", level:"Mid Level", category:"Situational", difficulty:"Easy", question:"A senior executive questions the accuracy of your dashboard during a meeting. How do you respond?", hint:"Stay calm, acknowledge concern, commit to investigate, don't guess, follow up with findings." },
  { id:383, role:"Data Analyst", level:"Mid Level", category:"Situational", difficulty:"Medium", question:"You notice a sudden spike in a key business metric. How do you investigate?", hint:"Rule out data issues first, segment analysis, time correlation with events/releases, hypothesis test." },
  { id:384, role:"Data Analyst", level:"Mid Level", category:"Situational", difficulty:"Hard", question:"You're asked to build a single dashboard that satisfies the CEO, sales VP, and marketing director. How do you approach this?", hint:"Separate needs via interviews, role-based views or tabs, shared KPIs + role-specific metrics." },
  { id:385, role:"Data Analyst", level:"Mid Level", category:"Culture Fit", difficulty:"Easy", question:"How do you build trust with business stakeholders as an analyst?", hint:"Proactive communication, reliable delivery, ask good questions, follow up, share back impact." },
  { id:386, role:"Data Analyst", level:"Mid Level", category:"Culture Fit", difficulty:"Medium", question:"How do you foster data literacy in teams that don't have a technical background?", hint:"Workshops, templates, SQL lite, doc standards, self-service tools, celebrate data-driven decisions." },
  { id:387, role:"Data Analyst", level:"Mid Level", category:"Culture Fit", difficulty:"Hard", question:"How do you handle a situation where your analysis is technically correct but contradicts your company's narrative?", hint:"Present honestly, frame carefully, prepare for challenge, back up with methodology, protect your integrity." },
  { id:388, role:"Data Analyst", level:"Mid Level", category:"Case Study", difficulty:"Easy", question:"How would you design a product usage dashboard for a SaaS application?", hint:"DAU/MAU, feature adoption, session duration, retention, NPS, filter by plan/segment." },
  { id:389, role:"Data Analyst", level:"Mid Level", category:"Case Study", difficulty:"Medium", question:"How would you analyze whether a loyalty program is working?", hint:"Member vs non-member spend, purchase frequency, retention, incremental revenue, program cost." },
  { id:390, role:"Data Analyst", level:"Mid Level", category:"Case Study", difficulty:"Hard", question:"Design an analytics system to detect anomalies in financial transactions.", hint:"Statistical control charts, z-scores, isolation forest, domain rules, alert tuning, false positive rate." },

  { id:391, role:"Data Analyst", level:"Senior Level", category:"Technical", difficulty:"Easy", question:"What is dbt (data build tool) and what problems does it solve?", hint:"Transforms data in warehouse using SQL + Jinja, version control, testing, documentation, lineage." },
  { id:392, role:"Data Analyst", level:"Senior Level", category:"Technical", difficulty:"Medium", question:"How do you design a data governance framework for an analytics team?", hint:"Data catalog, ownership model, quality standards, access control, lineage, retention policies." },
  { id:393, role:"Data Analyst", level:"Senior Level", category:"Technical", difficulty:"Hard", question:"How do you build a reliable real-time analytics pipeline?", hint:"Kafka/Kinesis, stream processing (Flink/Spark Streaming), exactly-once semantics, monitoring." },
  { id:394, role:"Data Analyst", level:"Senior Level", category:"Behavioral", difficulty:"Easy", question:"How do you mentor junior analysts on your team?", hint:"Code review for SQL, hypothesis thinking, presentation skills, structured feedback, safe scope." },
  { id:395, role:"Data Analyst", level:"Senior Level", category:"Behavioral", difficulty:"Medium", question:"How have you led an analytics project from scoping to delivery?", hint:"Stakeholder alignment, define metrics, data exploration, modeling, storytelling, handoff." },
  { id:396, role:"Data Analyst", level:"Senior Level", category:"Behavioral", difficulty:"Hard", question:"Tell me about a time you drove a significant change in how your company uses data.", hint:"Culture change, tooling adoption, process improvement, exec buy-in, long-term impact." },
  { id:397, role:"Data Analyst", level:"Senior Level", category:"Situational", difficulty:"Easy", question:"The company is launching a new product. How do you set up measurement from day one?", hint:"Define success metrics upfront, instrument before launch, baseline, A/B framework, data contracts." },
  { id:398, role:"Data Analyst", level:"Senior Level", category:"Situational", difficulty:"Medium", question:"Your data warehouse query costs have tripled this month. How do you investigate and fix it?", hint:"Query profiler, identify expensive queries, caching, materialization strategy, user education." },
  { id:399, role:"Data Analyst", level:"Senior Level", category:"Situational", difficulty:"Hard", question:"Two business units report conflicting metrics to leadership. How do you resolve it?", hint:"Common definitions, single source of truth, semantic layer, governance process, executive alignment." },
  { id:400, role:"Data Analyst", level:"Senior Level", category:"Culture Fit", difficulty:"Easy", question:"What does good data culture mean to you?", hint:"Data-driven not data-obsessed, questioning data quality, shared definitions, democratized access." },
  { id:401, role:"Data Analyst", level:"Senior Level", category:"Culture Fit", difficulty:"Medium", question:"How do you position analytics as a strategic function rather than a reporting service?", hint:"Proactive insights, impact measurement, seat at planning table, influence on roadmap." },
  { id:402, role:"Data Analyst", level:"Senior Level", category:"Culture Fit", difficulty:"Hard", question:"How do you handle conflicting priorities between depth of analysis and breadth of coverage?", hint:"Prioritization framework, tier requests, dedicated deep-dive time, self-service for routine requests." },
  { id:403, role:"Data Analyst", level:"Senior Level", category:"Case Study", difficulty:"Easy", question:"How would you design a KPI framework for a retail chain?", hint:"Revenue, margin, foot traffic, conversion, basket size, inventory turns, NPS. Cascade from company to store." },
  { id:404, role:"Data Analyst", level:"Senior Level", category:"Case Study", difficulty:"Medium", question:"How would you evaluate the effectiveness of a company's pricing strategy using data?", hint:"Price elasticity, competitive benchmarking, margin analysis, segment response, A/B testing." },
  { id:405, role:"Data Analyst", level:"Senior Level", category:"Case Study", difficulty:"Hard", question:"Design a KPI reporting system for a retail chain with 500 stores.", hint:"Metric hierarchy, data sources, refresh cadence, drill-down capability, anomaly detection, governance." },

  { id:406, role:"Data Analyst", level:"Lead / Manager", category:"Technical", difficulty:"Easy", question:"How do you evaluate analytics tools and vendors for your team?", hint:"Capabilities fit, total cost, learning curve, integration, support, scalability, team adoption." },
  { id:407, role:"Data Analyst", level:"Lead / Manager", category:"Technical", difficulty:"Medium", question:"How do you build a data catalog and ensure it stays up to date?", hint:"Automated discovery, ownership model, SLA for documentation, gamification, integration with workflow." },
  { id:408, role:"Data Analyst", level:"Lead / Manager", category:"Technical", difficulty:"Hard", question:"How would you architect the analytics infrastructure for a fast-growing startup?", hint:"Modern data stack (Fivetran/dbt/Snowflake/Looker), cost-aware, future-proof, team skill match." },
  { id:409, role:"Data Analyst", level:"Lead / Manager", category:"Behavioral", difficulty:"Easy", question:"How do you hire great analysts? What do you look for beyond SQL skills?", hint:"Curiosity, business acumen, communication, intellectual honesty, comfort with ambiguity." },
  { id:410, role:"Data Analyst", level:"Lead / Manager", category:"Behavioral", difficulty:"Medium", question:"How do you manage an analytics team that supports multiple business verticals?", hint:"Embedded vs centralized tradeoffs, shared standards, capacity model, escalation paths." },
  { id:411, role:"Data Analyst", level:"Lead / Manager", category:"Behavioral", difficulty:"Hard", question:"Describe how you've built a data team from scratch.", hint:"Hire order, tooling decisions, process setup, stakeholder relationships, quick wins, growth." },
  { id:412, role:"Data Analyst", level:"Lead / Manager", category:"Situational", difficulty:"Easy", question:"Your team is asked to take on twice the work with no new headcount. How do you respond?", hint:"Prioritize, identify automation opportunities, push back with data, protect quality work." },
  { id:413, role:"Data Analyst", level:"Lead / Manager", category:"Situational", difficulty:"Medium", question:"A major stakeholder is losing trust in your team's data. How do you rebuild it?", hint:"Audit past issues, transparent communication, data quality SLA, regular check-ins, demonstrate improvement." },
  { id:414, role:"Data Analyst", level:"Lead / Manager", category:"Situational", difficulty:"Hard", question:"The company wants to become 'data-driven' but has no data culture. How do you lead this transformation?", hint:"Executive sponsorship, quick wins, democratize access, training, incentive alignment, celebrate wins." },
  { id:415, role:"Data Analyst", level:"Lead / Manager", category:"Culture Fit", difficulty:"Easy", question:"What is your philosophy on self-service analytics vs. centralized analysis?", hint:"Both have place: self-service for operational, centralized for strategic. Governance is key." },
  { id:416, role:"Data Analyst", level:"Lead / Manager", category:"Culture Fit", difficulty:"Medium", question:"How do you build accountability for data quality across teams that produce data?", hint:"Data ownership, quality SLAs, automated monitoring, feedback loops to producers, incentives." },
  { id:417, role:"Data Analyst", level:"Lead / Manager", category:"Culture Fit", difficulty:"Hard", question:"How do you balance the need for data democratization with data security and governance?", hint:"Role-based access, data tiers, privacy by design, training, audit logs, governance committee." },
  { id:418, role:"Data Analyst", level:"Lead / Manager", category:"Case Study", difficulty:"Easy", question:"How would you present a quarterly business review to the executive team using data?", hint:"Lead with 3 headlines, then support, compare to target, segment highlights, forward-looking metrics." },
  { id:419, role:"Data Analyst", level:"Lead / Manager", category:"Case Study", difficulty:"Medium", question:"Design a data quality monitoring system for a critical business dataset.", hint:"Completeness, accuracy, timeliness, consistency checks. Alerting, ownership, SLA, remediation path." },
  { id:420, role:"Data Analyst", level:"Lead / Manager", category:"Case Study", difficulty:"Hard", question:"How would you build an analytics center of excellence for a 500-person company?", hint:"Mission, team structure, tooling standards, training program, governance, stakeholder engagement model." },

  // ═══════════════════════════════════════════════════════════
  // MACHINE LEARNING ENGINEER
  // ═══════════════════════════════════════════════════════════

  { id:421, role:"Machine Learning Engineer", level:"Entry Level", category:"Technical", difficulty:"Easy", question:"What is the difference between a training set, validation set, and test set?", hint:"Train: fit model. Validate: tune hyperparameters. Test: final unbiased evaluation. Never leak test into training." },
  { id:422, role:"Machine Learning Engineer", level:"Entry Level", category:"Technical", difficulty:"Easy", question:"What are the most common Python libraries used in machine learning?", hint:"NumPy, pandas, scikit-learn, TensorFlow/PyTorch, Matplotlib/Seaborn, Hugging Face." },
  { id:423, role:"Machine Learning Engineer", level:"Entry Level", category:"Technical", difficulty:"Medium", question:"What is gradient descent and how does it work?", hint:"Minimize loss by iteratively moving in direction of negative gradient. Learning rate controls step size." },
  { id:424, role:"Machine Learning Engineer", level:"Entry Level", category:"Technical", difficulty:"Medium", question:"Explain the difference between batch, mini-batch, and stochastic gradient descent.", hint:"Batch: all data per update (slow, stable). SGD: one sample (noisy, fast). Mini-batch: best of both." },
  { id:425, role:"Machine Learning Engineer", level:"Entry Level", category:"Technical", difficulty:"Hard", question:"What is a confusion matrix? Explain TP, FP, TN, FN and how you derive precision, recall, F1.", hint:"TP: correct positive. FP: false alarm. TN: correct negative. FN: missed positive. F1 = harmonic mean." },
  { id:426, role:"Machine Learning Engineer", level:"Entry Level", category:"Technical", difficulty:"Hard", question:"What is backpropagation and how does it enable neural network training?", hint:"Chain rule applied to compute gradients layer by layer. Enables weight updates via gradient descent." },
  { id:427, role:"Machine Learning Engineer", level:"Entry Level", category:"Behavioral", difficulty:"Easy", question:"Tell me about an ML project you built. What was the problem and how did you approach it?", hint:"Problem, data, model choice, evaluation, deployment. Show end-to-end ownership." },
  { id:428, role:"Machine Learning Engineer", level:"Entry Level", category:"Behavioral", difficulty:"Medium", question:"How do you decide which ML algorithm to use for a given problem?", hint:"Problem type (classification/regression/clustering), data size, interpretability needs, baseline first." },
  { id:429, role:"Machine Learning Engineer", level:"Entry Level", category:"Behavioral", difficulty:"Hard", question:"Tell me about a time a model you built performed worse than expected. What did you do?", hint:"Debug pipeline, check data quality, feature analysis, error analysis, iterate, don't just tune hyperparams." },
  { id:430, role:"Machine Learning Engineer", level:"Entry Level", category:"Situational", difficulty:"Easy", question:"You're given a new ML task with no labeled data. How do you proceed?", hint:"Check for weak supervision opportunities, unsupervised methods, data labeling strategy, transfer learning." },
  { id:431, role:"Machine Learning Engineer", level:"Entry Level", category:"Situational", difficulty:"Medium", question:"Your model achieves 95% accuracy but stakeholders are unhappy. Why might this be?", hint:"Imbalanced classes (95% baseline), wrong metric (precision/recall matters more), business cost of errors." },
  { id:432, role:"Machine Learning Engineer", level:"Entry Level", category:"Situational", difficulty:"Hard", question:"A model you trained locally runs 10x slower in production. How do you investigate?", hint:"CPU vs GPU, batch size, serialization, I/O bottleneck, model format, quantization, profiling." },
  { id:433, role:"Machine Learning Engineer", level:"Entry Level", category:"Culture Fit", difficulty:"Easy", question:"How do you stay current with advances in machine learning?", hint:"ArXiv, Papers with Code, conferences (NeurIPS/ICML/ICLR), Twitter/X ML community, replicate papers." },
  { id:434, role:"Machine Learning Engineer", level:"Entry Level", category:"Culture Fit", difficulty:"Medium", question:"How do you approach collaboration between ML engineers and data scientists?", hint:"Shared pipeline ownership, clear handoff points, mutual respect for skills, joint retrospectives." },
  { id:435, role:"Machine Learning Engineer", level:"Entry Level", category:"Culture Fit", difficulty:"Hard", question:"How do you balance research exploration with the engineering rigor needed for production ML?", hint:"Time-box experiments, code quality from day one, reproducibility, document research decisions." },
  { id:436, role:"Machine Learning Engineer", level:"Entry Level", category:"Case Study", difficulty:"Easy", question:"How would you build a simple spam classifier?", hint:"Feature engineering (TF-IDF or embeddings), logistic regression baseline, evaluation metrics (precision)." },
  { id:437, role:"Machine Learning Engineer", level:"Entry Level", category:"Case Study", difficulty:"Medium", question:"How would you design an image classification pipeline?", hint:"Data loading, augmentation, pre-trained CNN, fine-tuning, evaluation, inference optimization." },
  { id:438, role:"Machine Learning Engineer", level:"Entry Level", category:"Case Study", difficulty:"Hard", question:"How would you build a recommendation system for a new e-commerce platform with no existing user data?", hint:"Cold start: content-based, popularity-based, explore/exploit, collect implicit feedback fast." },

  { id:439, role:"Machine Learning Engineer", level:"Mid Level", category:"Technical", difficulty:"Easy", question:"What is transfer learning and when would you use it?", hint:"Pre-trained model weights as starting point. Useful with limited data, faster convergence, fewer epochs." },
  { id:440, role:"Machine Learning Engineer", level:"Mid Level", category:"Technical", difficulty:"Medium", question:"What is model quantization and when would you apply it?", hint:"Reduce precision (float32→int8). Smaller model, faster inference, slight accuracy tradeoff. Mobile/edge." },
  { id:441, role:"Machine Learning Engineer", level:"Mid Level", category:"Technical", difficulty:"Medium", question:"Explain attention mechanisms and why they transformed NLP.", hint:"Weights importance of each token relative to others. Enables parallelization, long-range dependencies." },
  { id:442, role:"Machine Learning Engineer", level:"Mid Level", category:"Technical", difficulty:"Hard", question:"How do you design an ML feature store? What problems does it solve?", hint:"Training-serving consistency, feature reuse, point-in-time correctness, online+offline duality." },
  { id:443, role:"Machine Learning Engineer", level:"Mid Level", category:"Technical", difficulty:"Hard", question:"What is model versioning and how do you implement it in an ML pipeline?", hint:"MLflow, DVC, model registry, artifact versioning, experiment tracking, reproducibility guarantees." },
  { id:444, role:"Machine Learning Engineer", level:"Mid Level", category:"Behavioral", difficulty:"Easy", question:"How do you approach feature engineering for a structured data problem?", hint:"Domain knowledge, correlation analysis, feature interactions, encoding strategies, missing value handling." },
  { id:445, role:"Machine Learning Engineer", level:"Mid Level", category:"Behavioral", difficulty:"Medium", question:"Describe how you've deployed and monitored an ML model in production.", hint:"Serving infrastructure, input validation, prediction logging, drift detection, alerting, retraining triggers." },
  { id:446, role:"Machine Learning Engineer", level:"Mid Level", category:"Behavioral", difficulty:"Hard", question:"Tell me about a time you improved model performance significantly. What was your approach?", hint:"Error analysis first, data quality, feature engineering, architecture change, ensembling, not just tuning." },
  { id:447, role:"Machine Learning Engineer", level:"Mid Level", category:"Situational", difficulty:"Easy", question:"You need to serve a large deep learning model with <50ms latency. How do you approach this?", hint:"Quantization, pruning, distillation, ONNX/TensorRT, async serving, caching, batching." },
  { id:448, role:"Machine Learning Engineer", level:"Mid Level", category:"Situational", difficulty:"Medium", question:"A deployed model's predictions are drifting over time. How do you detect and address this?", hint:"Input drift (feature distribution), concept drift (label relationship). Monitoring, alerting, retraining." },
  { id:449, role:"Machine Learning Engineer", level:"Mid Level", category:"Situational", difficulty:"Hard", question:"You need to run ML inference on 10M requests per day within a tight cost budget. How do you architect this?", hint:"Batch vs real-time split, model distillation, caching popular inputs, tiered serving, spot instances." },
  { id:450, role:"Machine Learning Engineer", level:"Mid Level", category:"Culture Fit", difficulty:"Easy", question:"How do you ensure reproducibility in your ML experiments?", hint:"Seed everything, version data and code, environment snapshots, experiment tracking, config files." },
  { id:451, role:"Machine Learning Engineer", level:"Mid Level", category:"Culture Fit", difficulty:"Medium", question:"How do you handle technical disagreements about model architecture choices?", hint:"Empirical testing, shared evaluation protocol, document assumptions, time-box debate, decide and commit." },
  { id:452, role:"Machine Learning Engineer", level:"Mid Level", category:"Culture Fit", difficulty:"Hard", question:"How do you think about the ethical implications of the models you build?", hint:"Bias auditing, fairness metrics, unintended use cases, data consent, impact assessment, transparency." },
  { id:453, role:"Machine Learning Engineer", level:"Mid Level", category:"Case Study", difficulty:"Easy", question:"How would you build a text summarization system for long documents?", hint:"Extractive vs abstractive, BART/T5 fine-tuning, evaluation (ROUGE), latency constraints, chunking." },
  { id:454, role:"Machine Learning Engineer", level:"Mid Level", category:"Case Study", difficulty:"Medium", question:"Design an ML pipeline for a real-time content moderation system.", hint:"Low latency classifier, confidence thresholds, human review queue, feedback loop, bias auditing." },
  { id:455, role:"Machine Learning Engineer", level:"Mid Level", category:"Case Study", difficulty:"Hard", question:"How would you build a model to predict equipment failure in an industrial setting?", hint:"Time-series features, anomaly detection, survival analysis, sparse labels, false positive cost vs recall." },

  { id:456, role:"Machine Learning Engineer", level:"Senior Level", category:"Technical", difficulty:"Easy", question:"What is knowledge distillation?", hint:"Train a smaller student model to mimic a larger teacher model. Soft targets carry more information." },
  { id:457, role:"Machine Learning Engineer", level:"Senior Level", category:"Technical", difficulty:"Medium", question:"How do you implement model versioning and reproducibility in an ML pipeline?", hint:"MLflow/DVC, artifact versioning, experiment metadata, data versioning, containerized training." },
  { id:458, role:"Machine Learning Engineer", level:"Senior Level", category:"Technical", difficulty:"Hard", question:"How would you design a low-latency, high-throughput ML serving system?", hint:"Model parallelism, request batching, GPU utilization, async I/O, autoscaling, SLA monitoring." },
  { id:459, role:"Machine Learning Engineer", level:"Senior Level", category:"Behavioral", difficulty:"Easy", question:"How do you evaluate whether to build a custom model vs use a pre-built API?", hint:"Accuracy requirements, data privacy, latency, cost, customizability, maintenance burden." },
  { id:460, role:"Machine Learning Engineer", level:"Senior Level", category:"Behavioral", difficulty:"Medium", question:"Tell me about a time you drove the adoption of ML best practices across your team.", hint:"What was broken, what you proposed, how you got buy-in, what changed, how you measured improvement." },
  { id:461, role:"Machine Learning Engineer", level:"Senior Level", category:"Behavioral", difficulty:"Hard", question:"Describe the most complex ML system you've built or contributed to. What were the key decisions?", hint:"Architecture, training infra, serving, monitoring, tradeoffs, what you'd change with hindsight." },
  { id:462, role:"Machine Learning Engineer", level:"Senior Level", category:"Situational", difficulty:"Easy", question:"You're asked to evaluate whether a new LLM-based feature is worth building. How do you approach it?", hint:"Define evaluation criteria, prototype, cost estimate, latency, accuracy, user value, build vs API." },
  { id:463, role:"Machine Learning Engineer", level:"Senior Level", category:"Situational", difficulty:"Medium", question:"A team wants to use a very large model (e.g. 70B parameters) in production. How do you respond?", hint:"Infrastructure cost, latency, alternatives (distillation, smaller fine-tuned models), ROI analysis." },
  { id:464, role:"Machine Learning Engineer", level:"Senior Level", category:"Situational", difficulty:"Hard", question:"Your ML system is making predictions that are technically accurate but causing unintended real-world harm. What do you do?", hint:"Immediately escalate, disable if severe, root cause, stakeholder communication, redesign with ethics." },
  { id:465, role:"Machine Learning Engineer", level:"Senior Level", category:"Culture Fit", difficulty:"Easy", question:"What does responsible AI mean to you in an engineering context?", hint:"Bias, transparency, accountability, data consent, model cards, impact assessment, ongoing monitoring." },
  { id:466, role:"Machine Learning Engineer", level:"Senior Level", category:"Culture Fit", difficulty:"Medium", question:"How do you build a culture of rigor and reproducibility on an ML team?", hint:"Experiment tracking by default, code review for notebooks, shared evaluation protocols, documentation." },
  { id:467, role:"Machine Learning Engineer", level:"Senior Level", category:"Culture Fit", difficulty:"Hard", question:"How do you approach the tradeoff between model interpretability and performance?", hint:"Regulatory requirements, stakeholder trust, black-box tools (SHAP/LIME), right tool for risk level." },
  { id:468, role:"Machine Learning Engineer", level:"Senior Level", category:"Case Study", difficulty:"Easy", question:"How would you design the evaluation framework for a generative AI feature?", hint:"Human eval, automated metrics, safety/toxicity, groundedness, latency, user feedback loops." },
  { id:469, role:"Machine Learning Engineer", level:"Senior Level", category:"Case Study", difficulty:"Medium", question:"Design a training pipeline for a large language model fine-tuning task.", hint:"Data curation, preprocessing, PEFT (LoRA/QLoRA), distributed training, evaluation, checkpoint management." },
  { id:470, role:"Machine Learning Engineer", level:"Senior Level", category:"Case Study", difficulty:"Hard", question:"How would you architect an ML platform for a team running 100+ experiments per week?", hint:"Experiment tracking, compute orchestration, artifact store, feature store, model registry, governance." },

  { id:471, role:"Machine Learning Engineer", level:"Lead / Manager", category:"Technical", difficulty:"Easy", question:"How do you set technical standards for ML code quality on your team?", hint:"Code review, linting, testing ML-specific (data validation, model tests), documentation, reproducibility." },
  { id:472, role:"Machine Learning Engineer", level:"Lead / Manager", category:"Technical", difficulty:"Medium", question:"How do you evaluate the cost and feasibility of a proposed ML system before committing to it?", hint:"Data availability, labeling cost, compute budget, latency SLA, maintenance, ROI." },
  { id:473, role:"Machine Learning Engineer", level:"Lead / Manager", category:"Technical", difficulty:"Hard", question:"How do you architect an MLOps platform that serves 50+ models across 10 teams?", hint:"Centralized vs federated, model registry, monitoring, retraining automation, governance, cost allocation." },
  { id:474, role:"Machine Learning Engineer", level:"Lead / Manager", category:"Behavioral", difficulty:"Easy", question:"How do you balance technical excellence with delivery speed on an ML team?", hint:"Ruthless prioritization, MVP model first, incremental quality, invest in infra to speed up long term." },
  { id:475, role:"Machine Learning Engineer", level:"Lead / Manager", category:"Behavioral", difficulty:"Medium", question:"How do you grow ML engineers who are strong technically but struggle with communication?", hint:"Targeted coaching, presentation opportunities, pair with strong communicators, structured feedback." },
  { id:476, role:"Machine Learning Engineer", level:"Lead / Manager", category:"Behavioral", difficulty:"Hard", question:"Tell me about a time you had to shut down an ML project that wasn't achieving results. How did you handle it?", hint:"Data-driven decision, team morale, preserve learnings, reframe as progress, move forward decisively." },
  { id:477, role:"Machine Learning Engineer", level:"Lead / Manager", category:"Situational", difficulty:"Easy", question:"Leadership wants to 'add AI' to everything. How do you manage this?", hint:"Problem-first thinking, where AI genuinely helps, prioritization framework, manage expectations." },
  { id:478, role:"Machine Learning Engineer", level:"Lead / Manager", category:"Situational", difficulty:"Medium", question:"Your ML platform is becoming a bottleneck for the data science team. How do you address it?", hint:"Gather specific pain points, triage, dedicated infra sprints, platform SLA, roadmap communication." },
  { id:479, role:"Machine Learning Engineer", level:"Lead / Manager", category:"Situational", difficulty:"Hard", question:"A high-profile ML model causes a public incident due to biased outputs. How do you lead the response?", hint:"Immediate mitigation, transparent communication, root cause analysis, process overhaul, preventive audit." },
  { id:480, role:"Machine Learning Engineer", level:"Lead / Manager", category:"Culture Fit", difficulty:"Easy", question:"What is your philosophy on research vs applied ML in an engineering team?", hint:"Applied first, research tied to business problem, time-box exploration, publish internally." },
  { id:481, role:"Machine Learning Engineer", level:"Lead / Manager", category:"Culture Fit", difficulty:"Medium", question:"How do you build bridges between ML engineering and data science teams?", hint:"Shared processes, mutual respect, joint ownership of models, cross-team retrospectives." },
  { id:482, role:"Machine Learning Engineer", level:"Lead / Manager", category:"Culture Fit", difficulty:"Hard", question:"How do you create accountability for model performance in production across your org?", hint:"Ownership model, SLO for models, post-mortems, on-call, business outcome accountability." },
  { id:483, role:"Machine Learning Engineer", level:"Lead / Manager", category:"Case Study", difficulty:"Easy", question:"How would you structure a new ML engineering team joining an existing product org?", hint:"Embedding vs platform team, relationship with data science, first 90 days plan, quick wins." },
  { id:484, role:"Machine Learning Engineer", level:"Lead / Manager", category:"Case Study", difficulty:"Medium", question:"Design an ML model governance process for a regulated industry (e.g. finance or healthcare).", hint:"Model validation, bias auditing, documentation, audit trail, human oversight, regulatory alignment." },
  { id:485, role:"Machine Learning Engineer", level:"Lead / Manager", category:"Case Study", difficulty:"Hard", question:"How would you build an AI safety review process for models being deployed to millions of users?", hint:"Red teaming, adversarial testing, staged rollout, feedback mechanisms, kill switch, ongoing monitoring." },

  // ═══════════════════════════════════════════════════════════
  // FRONTEND DEVELOPER
  // ═══════════════════════════════════════════════════════════

  { id:486, role:"Frontend Developer", level:"Entry Level", category:"Technical", difficulty:"Easy", question:"What is CSS specificity and how is it calculated?", hint:"Inline > ID > Class/Pseudo/Attribute > Element. 0-0-0-0 notation. !important overrides all." },
  { id:487, role:"Frontend Developer", level:"Entry Level", category:"Technical", difficulty:"Easy", question:"What is the DOM and how does JavaScript interact with it?", hint:"Document Object Model: tree of HTML elements. JS manipulates via getElementById, querySelector, events." },
  { id:488, role:"Frontend Developer", level:"Entry Level", category:"Technical", difficulty:"Medium", question:"What is the difference between == and === in JavaScript?", hint:"== coerces types (0=='0' is true). === strict equality (type + value). Always prefer ===." },
  { id:489, role:"Frontend Developer", level:"Entry Level", category:"Technical", difficulty:"Medium", question:"Explain the event loop in JavaScript.", hint:"Call stack, Web APIs, callback queue, microtask queue. Promises before setTimeout. Non-blocking I/O." },
  { id:490, role:"Frontend Developer", level:"Entry Level", category:"Technical", difficulty:"Hard", question:"What is the difference between var, let, and const? Explain hoisting.", hint:"var: function scoped, hoisted. let/const: block scoped, TDZ. const: immutable binding (not value)." },
  { id:491, role:"Frontend Developer", level:"Entry Level", category:"Technical", difficulty:"Hard", question:"What is CORS and how does it work?", hint:"Cross-Origin Resource Sharing. Browser restriction on cross-origin requests. Preflight, Access-Control headers." },
  { id:492, role:"Frontend Developer", level:"Entry Level", category:"Behavioral", difficulty:"Easy", question:"Tell me about a frontend project you built that you're proud of.", hint:"Walk through challenge, solution, what you'd improve, what you learned, impact." },
  { id:493, role:"Frontend Developer", level:"Entry Level", category:"Behavioral", difficulty:"Medium", question:"How do you ensure your code works across different browsers?", hint:"Feature detection (not UA sniffing), polyfills, progressive enhancement, BrowserStack testing." },
  { id:494, role:"Frontend Developer", level:"Entry Level", category:"Behavioral", difficulty:"Hard", question:"Tell me about a time you had to debug a complex UI issue. How did you approach it?", hint:"Browser DevTools, console, network tab, isolate component, reproduce minimal case, check state." },
  { id:495, role:"Frontend Developer", level:"Entry Level", category:"Situational", difficulty:"Easy", question:"A design you need to implement looks great on desktop but the designer hasn't provided mobile specs. What do you do?", hint:"Discuss with designer, apply mobile-first principles, show prototype for approval, don't guess blindly." },
  { id:496, role:"Frontend Developer", level:"Entry Level", category:"Situational", difficulty:"Medium", question:"You're asked to build a feature that requires a complex animation. You've never done animations before. What do you do?", hint:"Research CSS vs JS animations, start with simple CSS, document your approach, timebox the spike." },
  { id:497, role:"Frontend Developer", level:"Entry Level", category:"Situational", difficulty:"Hard", question:"The page you built is significantly slower on mobile. How do you diagnose and fix it?", hint:"Lighthouse, render-blocking resources, large images, JavaScript bundle size, network waterfall." },
  { id:498, role:"Frontend Developer", level:"Entry Level", category:"Culture Fit", difficulty:"Easy", question:"How do you approach writing accessible HTML and CSS?", hint:"Semantic HTML, alt text, ARIA roles, keyboard navigation, color contrast, screen reader testing." },
  { id:499, role:"Frontend Developer", level:"Entry Level", category:"Culture Fit", difficulty:"Medium", question:"How do you keep your frontend skills sharp given how fast the ecosystem changes?", hint:"Follow TC39, MDN, newsletters, build things, don't chase every framework." },
  { id:500, role:"Frontend Developer", level:"Entry Level", category:"Culture Fit", difficulty:"Hard", question:"How do you decide when to use a framework vs vanilla JavaScript?", hint:"Project scale, team familiarity, maintenance burden, performance, over-engineering risk." },
  { id:501, role:"Frontend Developer", level:"Entry Level", category:"Case Study", difficulty:"Easy", question:"Build a simple to-do list app. Walk me through your architecture.", hint:"State management, CRUD operations, persistence (localStorage), component structure, UX." },
  { id:502, role:"Frontend Developer", level:"Entry Level", category:"Case Study", difficulty:"Medium", question:"How would you implement infinite scroll for a social media feed?", hint:"Intersection Observer API, pagination, virtualization (react-window), loading states, error handling." },
  { id:503, role:"Frontend Developer", level:"Entry Level", category:"Case Study", difficulty:"Hard", question:"Design a reusable form validation system in JavaScript.", hint:"Schema-based, async validation, error state management, UX (when to show errors), accessibility." },

  { id:504, role:"Frontend Developer", level:"Mid Level", category:"Technical", difficulty:"Easy", question:"What are web components and what problem do they solve?", hint:"Custom elements, shadow DOM, HTML templates. Framework-agnostic, reusable, encapsulated." },
  { id:505, role:"Frontend Developer", level:"Mid Level", category:"Technical", difficulty:"Medium", question:"Explain React's reconciliation algorithm and virtual DOM.", hint:"Diffing algorithm: same type updates, different type unmounts. Keys for list stability. Fiber architecture." },
  { id:506, role:"Frontend Developer", level:"Mid Level", category:"Technical", difficulty:"Medium", question:"What are the differences between server-side rendering, static site generation, and client-side rendering?", hint:"SSR: fresh per request. SSG: build-time. CSR: browser. Tradeoffs: performance, SEO, interactivity." },
  { id:507, role:"Frontend Developer", level:"Mid Level", category:"Technical", difficulty:"Hard", question:"How do you optimize a React app that has dozens of re-renders per second?", hint:"useMemo, useCallback, React.memo, virtualization, avoid object literals in JSX, profiler." },
  { id:508, role:"Frontend Developer", level:"Mid Level", category:"Technical", difficulty:"Hard", question:"What is code splitting and how do you implement it in a React app?", hint:"React.lazy + Suspense, dynamic import(), route-based splitting, webpack chunks, preloading." },
  { id:509, role:"Frontend Developer", level:"Mid Level", category:"Behavioral", difficulty:"Easy", question:"How do you collaborate with designers to ensure pixel-perfect implementation?", hint:"Early handoff review, style guide alignment, flag edge cases early, use Storybook/design system." },
  { id:510, role:"Frontend Developer", level:"Mid Level", category:"Behavioral", difficulty:"Medium", question:"Tell me about a significant performance improvement you made to a web app.", hint:"Baseline metrics, what you changed, measurement after, tools used (Lighthouse, WebPageTest)." },
  { id:511, role:"Frontend Developer", level:"Mid Level", category:"Behavioral", difficulty:"Hard", question:"Describe your approach to state management in a large React application.", hint:"Local vs global state decision, Context vs Redux vs Zustand, server state (React Query), normalize." },
  { id:512, role:"Frontend Developer", level:"Mid Level", category:"Situational", difficulty:"Easy", question:"You're asked to add a new feature to a legacy frontend codebase with no tests. How do you proceed?", hint:"Add tests before changing, understand current behavior, don't refactor and feature at same time." },
  { id:513, role:"Frontend Developer", level:"Mid Level", category:"Situational", difficulty:"Medium", question:"A product designer requests a UX pattern that would be technically difficult and inaccessible. How do you handle it?", hint:"Explain constraints, propose accessible alternative, show prototype, involve them in solution." },
  { id:514, role:"Frontend Developer", level:"Mid Level", category:"Situational", difficulty:"Hard", question:"Your team is debating between two frontend frameworks for a new project. How do you facilitate the decision?", hint:"Evaluation criteria (DX, performance, community, hiring), POC both, team vote, document rationale." },
  { id:515, role:"Frontend Developer", level:"Mid Level", category:"Culture Fit", difficulty:"Easy", question:"How do you approach code reviews on your frontend team?", hint:"Focus on correctness, performance, accessibility, readability. Ask questions, don't demand. Positive framing." },
  { id:516, role:"Frontend Developer", level:"Mid Level", category:"Culture Fit", difficulty:"Medium", question:"How do you balance adopting new technologies with maintaining a stable codebase?", hint:"Evaluate in non-critical area first, tech radar, team decision, migration plan, document." },
  { id:517, role:"Frontend Developer", level:"Mid Level", category:"Culture Fit", difficulty:"Hard", question:"How do you advocate for frontend performance as a first-class concern?", hint:"Business metrics (conversion, bounce rate), Web Vitals SLO, performance budget, automated testing." },
  { id:518, role:"Frontend Developer", level:"Mid Level", category:"Case Study", difficulty:"Easy", question:"How would you implement a real-time search-as-you-type feature?", hint:"Debouncing, cancel previous request (AbortController), loading state, empty state, highlight matches." },
  { id:519, role:"Frontend Developer", level:"Mid Level", category:"Case Study", difficulty:"Medium", question:"Design a drag-and-drop kanban board in React.", hint:"HTML5 DnD API or react-beautiful-dnd, state management, optimistic updates, accessibility." },
  { id:520, role:"Frontend Developer", level:"Mid Level", category:"Case Study", difficulty:"Hard", question:"How would you architect a micro-frontend system for a large enterprise application?", hint:"Module federation, routing strategy, shared state challenges, design system, independent deploys." },

  { id:521, role:"Frontend Developer", level:"Senior Level", category:"Technical", difficulty:"Easy", question:"What are Core Web Vitals and how do you optimize for them?", hint:"LCP (largest paint), FID/INP (interactivity), CLS (layout shift). Image opt, lazy load, avoid large JS." },
  { id:522, role:"Frontend Developer", level:"Senior Level", category:"Technical", difficulty:"Medium", question:"Explain how browser rendering works from HTML parsing to paint.", hint:"Parse HTML→DOM, CSS→CSSOM, Render Tree, Layout, Paint, Composite. Avoid layout thrashing." },
  { id:523, role:"Frontend Developer", level:"Senior Level", category:"Technical", difficulty:"Hard", question:"How do you design a component library that scales across multiple teams and products?", hint:"Token system, composability, versioning, changelog, docs, governance, adoption metrics." },
  { id:524, role:"Frontend Developer", level:"Senior Level", category:"Behavioral", difficulty:"Easy", question:"How do you approach mentoring junior frontend developers?", hint:"Code reviews as teaching, pair programming, safe stretch tasks, portfolio feedback, career growth." },
  { id:525, role:"Frontend Developer", level:"Senior Level", category:"Behavioral", difficulty:"Medium", question:"Describe a time you made a significant architectural decision for a frontend application.", hint:"Context, options considered, tradeoffs, decision, outcome, what you'd change." },
  { id:526, role:"Frontend Developer", level:"Senior Level", category:"Behavioral", difficulty:"Hard", question:"How have you improved developer experience for a frontend team?", hint:"Faster builds, better error messages, DX tooling, templates, docs, onboarding improvements." },
  { id:527, role:"Frontend Developer", level:"Senior Level", category:"Situational", difficulty:"Easy", question:"You're joining a team with a large amount of frontend technical debt. Where do you start?", hint:"Audit, categorize, quick wins vs strategic, build business case, tech debt backlog, incremental." },
  { id:528, role:"Frontend Developer", level:"Senior Level", category:"Situational", difficulty:"Medium", question:"Your frontend performance degrades after a major feature release. How do you investigate?", hint:"Compare bundles, Lighthouse delta, runtime profiling, new dependencies, render bottlenecks." },
  { id:529, role:"Frontend Developer", level:"Senior Level", category:"Situational", difficulty:"Hard", question:"You're tasked with migrating a large Angular app to React with no downtime. How do you approach this?", hint:"Strangler fig, shared routing, component-by-component migration, feature flags, rollback plan." },
  { id:530, role:"Frontend Developer", level:"Senior Level", category:"Culture Fit", difficulty:"Easy", question:"What does good frontend engineering culture look like to you?", hint:"Performance budgets, accessibility standards, collaborative design, testing culture, no blame." },
  { id:531, role:"Frontend Developer", level:"Senior Level", category:"Culture Fit", difficulty:"Medium", question:"How do you handle a situation where the design system doesn't meet a product team's specific needs?", hint:"Evaluate if unique, propose extension or variant, governance process, don't fork unilaterally." },
  { id:532, role:"Frontend Developer", level:"Senior Level", category:"Culture Fit", difficulty:"Hard", question:"How do you balance the frontend team's technical needs with product velocity demands?", hint:"Invest in DX, tech debt allocation, make the case with metrics, phased improvements." },
  { id:533, role:"Frontend Developer", level:"Senior Level", category:"Case Study", difficulty:"Easy", question:"How would you design a dark mode feature for a large web application?", hint:"CSS custom properties, prefers-color-scheme, user override, system-aware, flash prevention." },
  { id:534, role:"Frontend Developer", level:"Senior Level", category:"Case Study", difficulty:"Medium", question:"Design an offline-capable progressive web application.", hint:"Service workers, cache strategies (cache-first, network-first), background sync, manifest, push." },
  { id:535, role:"Frontend Developer", level:"Senior Level", category:"Case Study", difficulty:"Hard", question:"How would you build a real-time collaborative editing experience in the browser?", hint:"CRDT or OT, WebSockets, conflict resolution, cursor presence, optimistic updates, offline sync." },

  { id:536, role:"Frontend Developer", level:"Lead / Manager", category:"Technical", difficulty:"Easy", question:"How do you define and enforce frontend code quality standards?", hint:"ESLint, Prettier, Husky, code review process, quality checklist, automated checks in CI." },
  { id:537, role:"Frontend Developer", level:"Lead / Manager", category:"Technical", difficulty:"Medium", question:"How do you evaluate and adopt new frontend technologies for your team?", hint:"Tech radar, POC, community health, bundle impact, team skill, migration path, DX benefit." },
  { id:538, role:"Frontend Developer", level:"Lead / Manager", category:"Technical", difficulty:"Hard", question:"How do you architect a frontend platform that supports 30+ micro-frontends?", hint:"Module federation, shared dependency management, routing federation, CI/CD per MFE, design system." },
  { id:539, role:"Frontend Developer", level:"Lead / Manager", category:"Behavioral", difficulty:"Easy", question:"How do you grow frontend engineers into senior and staff roles?", hint:"Scope expansion, leadership opportunities, technical depth projects, sponsorship, stretch feedback." },
  { id:540, role:"Frontend Developer", level:"Lead / Manager", category:"Behavioral", difficulty:"Medium", question:"How do you manage the balance between standardization and team autonomy in a frontend org?", hint:"Core standards vs preference zones, team input on standards, escape hatch with justification." },
  { id:541, role:"Frontend Developer", level:"Lead / Manager", category:"Behavioral", difficulty:"Hard", question:"Tell me about a time you led a significant frontend modernization effort. What was the impact?", hint:"Case for change, stakeholder buy-in, phased execution, metrics, team experience, lessons." },
  { id:542, role:"Frontend Developer", level:"Lead / Manager", category:"Situational", difficulty:"Easy", question:"Your team's frontend build times have grown to 20 minutes. How do you address this?", hint:"Dependency audit, incremental builds, cache optimization, parallelization, Vite/Turbopack migration." },
  { id:543, role:"Frontend Developer", level:"Lead / Manager", category:"Situational", difficulty:"Medium", question:"A product team wants to bypass the design system to ship faster. How do you handle this?", hint:"Understand urgency, offer design system sprint, document exceptions, governance reminder, long-term cost." },
  { id:544, role:"Frontend Developer", level:"Lead / Manager", category:"Situational", difficulty:"Hard", question:"You're asked to hire a senior frontend engineer but none of your candidates meet your bar. How do you proceed?", hint:"Review bar, pipeline expansion, referrals, grow internal candidate, honest with hiring manager." },
  { id:545, role:"Frontend Developer", level:"Lead / Manager", category:"Culture Fit", difficulty:"Easy", question:"What is your philosophy on frontend testing?", hint:"Test behavior not implementation, pyramid (unit/integration/e2e), fast feedback, confidence over coverage." },
  { id:546, role:"Frontend Developer", level:"Lead / Manager", category:"Culture Fit", difficulty:"Medium", question:"How do you build a culture of web performance across product teams?", hint:"Performance budgets, Web Vitals tracking, champion program, visible dashboards, include in DoD." },
  { id:547, role:"Frontend Developer", level:"Lead / Manager", category:"Culture Fit", difficulty:"Hard", question:"How do you handle a high-performing senior engineer who consistently ignores team standards?", hint:"Direct conversation, understand why, involve in standards process, clear expectations, document." },
  { id:548, role:"Frontend Developer", level:"Lead / Manager", category:"Case Study", difficulty:"Easy", question:"How would you design a frontend onboarding experience for a new engineer joining your team?", hint:"Environment setup automation, codebase tour, first PR in day 1, buddy system, documentation." },
  { id:549, role:"Frontend Developer", level:"Lead / Manager", category:"Case Study", difficulty:"Medium", question:"Design a frontend performance monitoring system for a production application.", hint:"Real User Monitoring (RUM), Web Vitals tracking, synthetic testing, alerting on regressions, dashboards." },
  { id:550, role:"Frontend Developer", level:"Lead / Manager", category:"Case Study", difficulty:"Hard", question:"How would you plan and execute a migration from a class-based React codebase to hooks?", hint:"Incremental adoption, new code in hooks, codemods for simple cases, training, no big bang rewrite." },

  // ═══════════════════════════════════════════════════════════
  // BACKEND DEVELOPER
  // ═══════════════════════════════════════════════════════════

  { id:551, role:"Backend Developer", level:"Entry Level", category:"Technical", difficulty:"Easy", question:"What is the difference between a process and a thread?", hint:"Process: isolated memory space. Thread: shared memory within process. Context switching cost." },
  { id:552, role:"Backend Developer", level:"Entry Level", category:"Technical", difficulty:"Easy", question:"Explain RESTful API design principles.", hint:"Stateless, uniform interface, resource-based URLs, HTTP verbs, status codes, HATEOAS." },
  { id:553, role:"Backend Developer", level:"Entry Level", category:"Technical", difficulty:"Medium", question:"What are database transactions and why do ACID properties matter?", hint:"Atomicity, Consistency, Isolation, Durability. Prevent partial updates, concurrency issues, data corruption." },
  { id:554, role:"Backend Developer", level:"Entry Level", category:"Technical", difficulty:"Medium", question:"What is the difference between synchronous and asynchronous code execution?", hint:"Sync: blocks until complete. Async: non-blocking, callbacks/promises/async-await, better I/O." },
  { id:555, role:"Backend Developer", level:"Entry Level", category:"Technical", difficulty:"Hard", question:"What are database indexes and how do they work? When should you avoid them?", hint:"B-tree structure speeds up reads. Slows writes, uses storage. Avoid on low-cardinality, write-heavy cols." },
  { id:556, role:"Backend Developer", level:"Entry Level", category:"Technical", difficulty:"Hard", question:"Explain the difference between TCP and UDP. When would you use each?", hint:"TCP: reliable, ordered, slower. UDP: fast, no guarantee, good for streaming/gaming/DNS." },
  { id:557, role:"Backend Developer", level:"Entry Level", category:"Behavioral", difficulty:"Easy", question:"Tell me about a backend service you built. What were the main design decisions?", hint:"Language/framework, data model, API design, error handling, performance, what you'd change." },
  { id:558, role:"Backend Developer", level:"Entry Level", category:"Behavioral", difficulty:"Medium", question:"How do you approach debugging a backend service that's returning unexpected responses?", hint:"Logs, request tracing, reproduce with curl/postman, check input/output at each layer, check DB state." },
  { id:559, role:"Backend Developer", level:"Entry Level", category:"Behavioral", difficulty:"Hard", question:"Tell me about a time you had to optimize a backend service for performance. What did you do?", hint:"Profile first, identify bottleneck, caching, query optimization, async, don't guess." },
  { id:560, role:"Backend Developer", level:"Entry Level", category:"Situational", difficulty:"Easy", question:"A third-party API your service depends on is returning errors. How do you handle it?", hint:"Circuit breaker, retry with backoff, fallback, alert, check status page, communicate to users." },
  { id:561, role:"Backend Developer", level:"Entry Level", category:"Situational", difficulty:"Medium", question:"You need to add a new field to a production database table with millions of rows. How do you do it safely?", hint:"Add nullable first, backfill asynchronously, then add constraint, no lock on large tables, migration strategy." },
  { id:562, role:"Backend Developer", level:"Entry Level", category:"Situational", difficulty:"Hard", question:"Your API endpoint needs to go from handling 100 rps to 10,000 rps. What changes do you make?", hint:"Profile, add caching, connection pooling, async processing, horizontal scaling, DB read replicas." },
  { id:563, role:"Backend Developer", level:"Entry Level", category:"Culture Fit", difficulty:"Easy", question:"How do you write backend code that other developers can easily maintain?", hint:"Clear naming, documentation, small functions, tests, consistent error handling, no magic numbers." },
  { id:564, role:"Backend Developer", level:"Entry Level", category:"Culture Fit", difficulty:"Medium", question:"How do you approach writing tests for a backend service?", hint:"Unit (business logic), integration (DB/API), contract tests, test pyramid, mock external deps." },
  { id:565, role:"Backend Developer", level:"Entry Level", category:"Culture Fit", difficulty:"Hard", question:"How do you handle technical debt in a backend service you own?", hint:"Classify, estimate cost, business case, allocate sprint capacity, track, prioritize by risk." },
  { id:566, role:"Backend Developer", level:"Entry Level", category:"Case Study", difficulty:"Easy", question:"Design a simple REST API for a user authentication system.", hint:"POST /register, POST /login, JWT tokens, bcrypt passwords, refresh tokens, logout/revoke." },
  { id:567, role:"Backend Developer", level:"Entry Level", category:"Case Study", difficulty:"Medium", question:"How would you design a notification delivery service that supports email, SMS, and push?", hint:"Message queue, provider abstraction, retry logic, deduplication, delivery status tracking." },
  { id:568, role:"Backend Developer", level:"Entry Level", category:"Case Study", difficulty:"Hard", question:"Design a backend for a ride-sharing app. What are the core services and data models?", hint:"User, driver, ride, location services, matching, pricing, events, geospatial indexing." },

  { id:569, role:"Backend Developer", level:"Mid Level", category:"Technical", difficulty:"Easy", question:"What is connection pooling and why is it important?", hint:"Reuse database connections, avoid overhead of creating/tearing down per request. Pool size tuning." },
  { id:570, role:"Backend Developer", level:"Mid Level", category:"Technical", difficulty:"Medium", question:"What is GraphQL and how does it compare to REST?", hint:"Client specifies exact fields, single endpoint, no over/under-fetching. More complex schema/resolvers." },
  { id:571, role:"Backend Developer", level:"Mid Level", category:"Technical", difficulty:"Medium", question:"What are the trade-offs between synchronous and asynchronous processing in backend systems?", hint:"Sync: simpler, blocking. Async: better throughput, complex error handling, eventual consistency." },
  { id:572, role:"Backend Developer", level:"Mid Level", category:"Technical", difficulty:"Hard", question:"How do you implement idempotency in an API?", hint:"Idempotency key in header, store request hash, return same response on retry, TTL for keys." },
  { id:573, role:"Backend Developer", level:"Mid Level", category:"Technical", difficulty:"Hard", question:"What is the N+1 query problem and how do you solve it?", hint:"ORM loads related entities one at a time. Fix: eager loading (JOIN), DataLoader pattern, batch queries." },
  { id:574, role:"Backend Developer", level:"Mid Level", category:"Behavioral", difficulty:"Easy", question:"How do you design API contracts that allow for backward compatibility?", hint:"Versioning (URI or header), additive changes only, deprecation policy, Semantic Versioning." },
  { id:575, role:"Backend Developer", level:"Mid Level", category:"Behavioral", difficulty:"Medium", question:"Tell me about a time you designed a system that needed to handle high concurrency.", hint:"Lock strategy, connection pooling, async processing, queue-based, load testing, metrics." },
  { id:576, role:"Backend Developer", level:"Mid Level", category:"Behavioral", difficulty:"Hard", question:"Describe your approach to designing a service that needs to be both highly available and strongly consistent.", hint:"Mostly you can't have both. Discuss CP vs AP, use cases, compensation patterns, distributed locks." },
  { id:577, role:"Backend Developer", level:"Mid Level", category:"Situational", difficulty:"Easy", question:"You discover a slow SQL query that's affecting production performance. What do you do?", hint:"EXPLAIN plan, check indexes, rewrite if needed, add index, monitor, test in staging first." },
  { id:578, role:"Backend Developer", level:"Mid Level", category:"Situational", difficulty:"Medium", question:"You need to break a large monolith service into smaller services. How do you approach this?", hint:"Bounded contexts, strangler fig, API contracts first, shared DB risk, data migration, gradual." },
  { id:579, role:"Backend Developer", level:"Mid Level", category:"Situational", difficulty:"Hard", question:"Your service is failing silently — errors aren't surfacing properly. How do you fix this?", hint:"Structured logging, error tracking (Sentry), error propagation audit, unhandled promise rejections." },
  { id:580, role:"Backend Developer", level:"Mid Level", category:"Culture Fit", difficulty:"Easy", question:"How do you approach API versioning on your team?", hint:"URI vs header versioning, sunset policy, backwards compatibility rule, consumer-driven contracts." },
  { id:581, role:"Backend Developer", level:"Mid Level", category:"Culture Fit", difficulty:"Medium", question:"How do you ensure security best practices in your backend services?", hint:"Input validation, parameterized queries, secrets management, HTTPS, auth/authz, dependency scanning." },
  { id:582, role:"Backend Developer", level:"Mid Level", category:"Culture Fit", difficulty:"Hard", question:"How do you handle on-call responsibilities for a backend service you own?", hint:"Good runbooks, alert quality, clear escalation, post-mortems, track MTTR, fair rotation." },
  { id:583, role:"Backend Developer", level:"Mid Level", category:"Case Study", difficulty:"Easy", question:"Design a caching strategy for a high-read backend API.", hint:"Cache-aside, Redis, TTL, cache invalidation strategies, what to cache (not user-specific data)." },
  { id:584, role:"Backend Developer", level:"Mid Level", category:"Case Study", difficulty:"Medium", question:"How would you design a webhook delivery system?", hint:"Event queue, retry with exponential backoff, signature verification, delivery log, timeout handling." },
  { id:585, role:"Backend Developer", level:"Mid Level", category:"Case Study", difficulty:"Hard", question:"Design a distributed job scheduler that handles millions of jobs per day.", hint:"Priority queue, worker pool, deduplication, idempotent jobs, dead letter queue, monitoring." },

  { id:586, role:"Backend Developer", level:"Senior Level", category:"Technical", difficulty:"Easy", question:"What is eventual consistency and how do you design systems to handle it?", hint:"BASE model, compensating transactions, conflict resolution, user-facing implications, saga pattern." },
  { id:587, role:"Backend Developer", level:"Senior Level", category:"Technical", difficulty:"Medium", question:"What is the saga pattern and when would you use it?", hint:"Distributed transactions without 2PC. Choreography vs orchestration. Compensating transactions on failure." },
  { id:588, role:"Backend Developer", level:"Senior Level", category:"Technical", difficulty:"Hard", question:"How would you design a multi-tenant SaaS backend architecture?", hint:"Isolation models (shared DB, schema-per-tenant, DB-per-tenant), data partitioning, auth, costs." },
  { id:589, role:"Backend Developer", level:"Senior Level", category:"Behavioral", difficulty:"Easy", question:"How do you approach system design reviews for junior engineers' proposals?", hint:"Mentor not rewrite. Ask probing questions, explore tradeoffs together, build confidence." },
  { id:590, role:"Backend Developer", level:"Senior Level", category:"Behavioral", difficulty:"Medium", question:"Tell me about the most complex backend system you've designed.", hint:"Requirements, choices, tradeoffs, scale challenges, what you learned, what you'd do differently." },
  { id:591, role:"Backend Developer", level:"Senior Level", category:"Behavioral", difficulty:"Hard", question:"How do you think about security when designing backend systems?", hint:"Threat modeling, principle of least privilege, defense in depth, secure defaults, OWASP Top 10." },
  { id:592, role:"Backend Developer", level:"Senior Level", category:"Situational", difficulty:"Easy", question:"You're asked to support a new client that requires data residency in the EU. How do you approach this?", hint:"GDPR, data routing, regional deployment, data classification, legal review, architecture changes." },
  { id:593, role:"Backend Developer", level:"Senior Level", category:"Situational", difficulty:"Medium", question:"Your service is experiencing data inconsistency between two microservices. How do you investigate?", hint:"Event ordering, idempotency, duplicate processing, missing events, eventual consistency window." },
  { id:594, role:"Backend Developer", level:"Senior Level", category:"Situational", difficulty:"Hard", question:"You need to implement a zero-downtime database schema migration for a table with 500 million rows.", hint:"Expand-contract pattern, dual-write, backfill script, cutover with flag, monitor lag." },
  { id:595, role:"Backend Developer", level:"Senior Level", category:"Culture Fit", difficulty:"Easy", question:"What does good backend engineering culture look like to you?", hint:"Ownership, observability-first, blameless post-mortems, documented decisions, reliability culture." },
  { id:596, role:"Backend Developer", level:"Senior Level", category:"Culture Fit", difficulty:"Medium", question:"How do you ensure your backend team has shared ownership of the platform's reliability?", hint:"On-call rotation, shared dashboards, post-mortem participation, SLO awareness, blameless culture." },
  { id:597, role:"Backend Developer", level:"Senior Level", category:"Culture Fit", difficulty:"Hard", question:"How do you balance the need to move fast and add new backend services vs. managing operational overhead?", hint:"Service maturity model, runbook requirement, paved roads, operational cost as part of design." },
  { id:598, role:"Backend Developer", level:"Senior Level", category:"Case Study", difficulty:"Easy", question:"Design an API gateway for a microservices architecture.", hint:"Auth, rate limiting, routing, load balancing, logging, circuit breaking, protocol translation." },
  { id:599, role:"Backend Developer", level:"Senior Level", category:"Case Study", difficulty:"Medium", question:"How would you design a payment processing system? What are the critical reliability requirements?", hint:"Idempotency, exactly-once, PCI compliance, reconciliation, audit log, retry safety, double charge." },
  { id:600, role:"Backend Developer", level:"Senior Level", category:"Case Study", difficulty:"Hard", question:"Design the backend for a real-time multiplayer game with leaderboards.", hint:"WebSocket, game state sync, conflict resolution, low latency architecture, leaderboard data structure." },

  { id:601, role:"Backend Developer", level:"Lead / Manager", category:"Technical", difficulty:"Easy", question:"How do you set technical standards for backend services across multiple teams?", hint:"RFC process, ADRs, internal SDKs/libraries, code review guidelines, architecture review board." },
  { id:602, role:"Backend Developer", level:"Lead / Manager", category:"Technical", difficulty:"Medium", question:"How do you manage API deprecation across a large engineering organization?", hint:"Versioning policy, sunset timeline, consumer notification, usage tracking, automated warnings." },
  { id:603, role:"Backend Developer", level:"Lead / Manager", category:"Technical", difficulty:"Hard", question:"How would you design the service mesh and communication strategy for a 100-service microservices platform?", hint:"gRPC vs REST, service discovery, mTLS, observability, circuit breaking, distributed tracing." },
  { id:604, role:"Backend Developer", level:"Lead / Manager", category:"Behavioral", difficulty:"Easy", question:"How do you develop backend engineers from mid-level to senior?", hint:"Ownership of end-to-end systems, architectural decisions, cross-team impact, structured feedback." },
  { id:605, role:"Backend Developer", level:"Lead / Manager", category:"Behavioral", difficulty:"Medium", question:"How do you create a culture of reliability engineering in a backend team?", hint:"SLOs, error budgets, post-mortems, on-call best practices, automation-first, reliability as feature." },
  { id:606, role:"Backend Developer", level:"Lead / Manager", category:"Behavioral", difficulty:"Hard", question:"Tell me about a time you drove a significant backend architecture change across multiple teams.", hint:"Building consensus, migration playbook, risk management, stakeholder communication, long-term ownership." },
  { id:607, role:"Backend Developer", level:"Lead / Manager", category:"Situational", difficulty:"Easy", question:"Two backend teams are building the same capability independently. How do you resolve this?", hint:"Surface early, shared service ownership, API contract first, avoid duplication, assign owner." },
  { id:608, role:"Backend Developer", level:"Lead / Manager", category:"Situational", difficulty:"Medium", question:"Your platform is experiencing frequent incidents due to poor service boundaries. How do you fix this?", hint:"Domain analysis, bounded context review, dependency audit, ownership matrix, circuit breakers." },
  { id:609, role:"Backend Developer", level:"Lead / Manager", category:"Situational", difficulty:"Hard", question:"Leadership wants to outsource backend development to reduce costs. How do you respond?", hint:"Quantify risks (quality, security, velocity), knowledge transfer cost, hybrid model proposal, data." },
  { id:610, role:"Backend Developer", level:"Lead / Manager", category:"Culture Fit", difficulty:"Easy", question:"What is your philosophy on building backend systems for the long term?", hint:"Evolutionary architecture, simplicity over cleverness, observable by default, good docs, own the ops." },
  { id:611, role:"Backend Developer", level:"Lead / Manager", category:"Culture Fit", difficulty:"Medium", question:"How do you build a strong sense of ownership in a backend team?", hint:"End-to-end responsibility, on-call participation, product metrics visibility, celebrate team wins." },
  { id:612, role:"Backend Developer", level:"Lead / Manager", category:"Culture Fit", difficulty:"Hard", question:"How do you retain strong backend engineers in a competitive talent market?", hint:"Challenging work, growth paths, autonomy, fair compensation, recognition, impact visibility." },
  { id:613, role:"Backend Developer", level:"Lead / Manager", category:"Case Study", difficulty:"Easy", question:"How would you design the backend architecture for a startup's MVP?", hint:"Monolith first, PostgreSQL, simple queue, managed services, fast to iterate, avoid premature scaling." },
  { id:614, role:"Backend Developer", level:"Lead / Manager", category:"Case Study", difficulty:"Medium", question:"How would you plan a backend platform re-architecture for a company that has grown 10x?", hint:"Pain point audit, strangler fig, team topology alignment, phased migration, zero-downtime goal." },
  { id:615, role:"Backend Developer", level:"Lead / Manager", category:"Case Study", difficulty:"Hard", question:"Design the backend infrastructure strategy for a company expanding from 1 region to 5 global regions.", hint:"Data residency, latency optimization, replication strategy, regional failover, cost, compliance." },

  // ═══════════════════════════════════════════════════════════
  // BUSINESS ANALYST
  // ═══════════════════════════════════════════════════════════

  { id:616, role:"Business Analyst", level:"Entry Level", category:"Technical", difficulty:"Easy", question:"What is a use case diagram and when would you use it?", hint:"Actors, use cases, system boundary. Shows functional requirements from user perspective. Not for design." },
  { id:617, role:"Business Analyst", level:"Entry Level", category:"Technical", difficulty:"Easy", question:"What is the difference between functional and non-functional requirements?", hint:"Functional: what the system does (login, search). NFR: how well (performance, security, scalability)." },
  { id:618, role:"Business Analyst", level:"Entry Level", category:"Technical", difficulty:"Medium", question:"What is SWOT analysis and when would you apply it?", hint:"Strengths, Weaknesses, Opportunities, Threats. Strategic planning, competitive analysis, decision support." },
  { id:619, role:"Business Analyst", level:"Entry Level", category:"Technical", difficulty:"Medium", question:"What is requirements traceability and why is it important?", hint:"Link requirements to design, code, tests. Ensures coverage, change impact analysis, compliance." },
  { id:620, role:"Business Analyst", level:"Entry Level", category:"Technical", difficulty:"Hard", question:"What is process mapping and what are the different levels of process models?", hint:"Level 0: high-level. Level 1-3: increasingly detailed. BPMN, swimlane diagrams, value stream mapping." },
  { id:621, role:"Business Analyst", level:"Entry Level", category:"Technical", difficulty:"Hard", question:"What is data flow diagrams (DFD)? Explain the differences between context, level 0, and level 1 diagrams.", hint:"Context: single process, external entities. L0: major processes. L1: explodes each L0 process." },
  { id:622, role:"Business Analyst", level:"Entry Level", category:"Behavioral", difficulty:"Easy", question:"Tell me about a time you gathered requirements from a difficult stakeholder.", hint:"Active listening, ask open-ended questions, paraphrase back, validate assumptions, build rapport." },
  { id:623, role:"Business Analyst", level:"Entry Level", category:"Behavioral", difficulty:"Medium", question:"How do you handle conflicting requirements from different stakeholders?", hint:"Document conflicts, facilitate discussion, prioritize by business value, escalate if needed, document decision." },
  { id:624, role:"Business Analyst", level:"Entry Level", category:"Behavioral", difficulty:"Hard", question:"Describe a time you identified a requirement that turned out to be the wrong solution to the right problem.", hint:"Root cause analysis, asking 'why', uncovering actual business need vs stated need." },
  { id:625, role:"Business Analyst", level:"Entry Level", category:"Situational", difficulty:"Easy", question:"A stakeholder says 'the system should be fast'. How do you turn this into a real requirement?", hint:"Quantify: specific pages, response time threshold, concurrent users, measurement method." },
  { id:626, role:"Business Analyst", level:"Entry Level", category:"Situational", difficulty:"Medium", question:"You're asked to analyze a process you know nothing about. How do you approach it?", hint:"Background research, shadow sessions, stakeholder interviews, current state walkthrough, document as-is." },
  { id:627, role:"Business Analyst", level:"Entry Level", category:"Situational", difficulty:"Hard", question:"Stakeholders keep changing their requirements mid-project. How do you manage this?", hint:"Change control process, impact assessment, communicate cost/time impact, formal change log, prioritization." },
  { id:628, role:"Business Analyst", level:"Entry Level", category:"Culture Fit", difficulty:"Easy", question:"How do you build trust with both business stakeholders and technical teams?", hint:"Deliver accurately, translate between languages, follow through, be transparent, meet people where they are." },
  { id:629, role:"Business Analyst", level:"Entry Level", category:"Culture Fit", difficulty:"Medium", question:"How do you ensure that your requirements documentation stays current as a project evolves?", hint:"Version control, regular reviews, requirement owner, change log, automated links to user stories." },
  { id:630, role:"Business Analyst", level:"Entry Level", category:"Culture Fit", difficulty:"Hard", question:"How do you handle a situation where a stakeholder has unrealistic expectations about project scope?", hint:"Document expectations vs reality, use data to show gap, phased delivery, negotiate priorities." },
  { id:631, role:"Business Analyst", level:"Entry Level", category:"Case Study", difficulty:"Easy", question:"Walk me through how you'd gather requirements for a new expense reporting system.", hint:"Stakeholder map, interviews, observe current process, pain points, as-is vs to-be, prioritize." },
  { id:632, role:"Business Analyst", level:"Entry Level", category:"Case Study", difficulty:"Medium", question:"How would you analyze whether a company should build or buy a CRM system?", hint:"Requirements match, customization needs, TCO, integration, data migration, vendor risk, timeline." },
  { id:633, role:"Business Analyst", level:"Entry Level", category:"Case Study", difficulty:"Hard", question:"Design a requirements workshop for a complex multi-stakeholder ERP implementation.", hint:"Agenda, facilitation techniques, pre-work, cross-functional participation, conflict resolution, output." },

  { id:634, role:"Business Analyst", level:"Mid Level", category:"Technical", difficulty:"Easy", question:"What is a BRD (Business Requirements Document) and what should it contain?", hint:"Scope, business objectives, stakeholders, functional/NFR requirements, assumptions, constraints." },
  { id:635, role:"Business Analyst", level:"Mid Level", category:"Technical", difficulty:"Medium", question:"What is gap analysis and when would you apply it?", hint:"Current state vs desired state, root cause, roadmap to close gap. Used in process improvement, system selection." },
  { id:636, role:"Business Analyst", level:"Mid Level", category:"Technical", difficulty:"Medium", question:"Explain the difference between agile and waterfall approaches to requirements.", hint:"Agile: iterative, just-in-time, user stories. Waterfall: upfront, comprehensive, formal change control." },
  { id:637, role:"Business Analyst", level:"Mid Level", category:"Technical", difficulty:"Hard", question:"How do you perform a cost-benefit analysis for a proposed IT initiative?", hint:"Tangible vs intangible benefits, NPV, ROI, payback period, risk-adjusted, sensitivity analysis." },
  { id:638, role:"Business Analyst", level:"Mid Level", category:"Technical", difficulty:"Hard", question:"What is a RACI matrix and when is it useful?", hint:"Responsible, Accountable, Consulted, Informed. Clarify decision rights, reduce confusion, useful in large projects." },
  { id:639, role:"Business Analyst", level:"Mid Level", category:"Behavioral", difficulty:"Easy", question:"How do you facilitate a productive requirements workshop?", hint:"Clear objective, diverse stakeholders, structured agenda, parking lot, visual aids, action items, follow-up." },
  { id:640, role:"Business Analyst", level:"Mid Level", category:"Behavioral", difficulty:"Medium", question:"Tell me about a project where you identified a significant business opportunity through your analysis.", hint:"How you found it, validated it, communicated it, what changed as a result." },
  { id:641, role:"Business Analyst", level:"Mid Level", category:"Behavioral", difficulty:"Hard", question:"Describe a time you managed a high-stakes stakeholder who was resistant to change.", hint:"Empathy, understand their resistance, address concerns directly, small wins, executive alignment." },
  { id:642, role:"Business Analyst", level:"Mid Level", category:"Situational", difficulty:"Easy", question:"A project is three months in and the requirements are completely changing. What do you do?", hint:"Impact assessment, formal change request, reprioritize, update estimates, stakeholder communication." },
  { id:643, role:"Business Analyst", level:"Mid Level", category:"Situational", difficulty:"Medium", question:"You discover that two business units have completely different processes for the same function. How do you approach harmonizing them?", hint:"Document both, find common ground, differences that matter, business case for standardization, governance." },
  { id:644, role:"Business Analyst", level:"Mid Level", category:"Situational", difficulty:"Hard", question:"Leadership wants to launch a new product, but your analysis shows the business case is weak. What do you do?", hint:"Present data honestly, quantify risk, propose alternatives, document your analysis, don't suppress findings." },
  { id:645, role:"Business Analyst", level:"Mid Level", category:"Culture Fit", difficulty:"Easy", question:"How do you maintain objectivity as a BA when you have a personal opinion about the solution?", hint:"Separate analysis from advocacy. Present findings, let data drive, share opinion as opinion not fact." },
  { id:646, role:"Business Analyst", level:"Mid Level", category:"Culture Fit", difficulty:"Medium", question:"How do you collaborate with UX designers on a shared project?", hint:"Requirements as input, validate against user needs together, JTBD framework, shared user research." },
  { id:647, role:"Business Analyst", level:"Mid Level", category:"Culture Fit", difficulty:"Hard", question:"How do you build your reputation as a trusted advisor to senior stakeholders?", hint:"Deliver accurately, bring insights not just information, challenge constructively, be reliable, follow up." },
  { id:648, role:"Business Analyst", level:"Mid Level", category:"Case Study", difficulty:"Easy", question:"How would you document the current state of a customer service process?", hint:"Process walkthrough, swimlane diagram, pain points, cycle time, handoffs, exception paths." },
  { id:649, role:"Business Analyst", level:"Mid Level", category:"Case Study", difficulty:"Medium", question:"Analyze the feasibility of implementing a new loyalty program for a retail chain.", hint:"Business objectives, customer behavior data, technical requirements, cost model, competitive landscape." },
  { id:650, role:"Business Analyst", level:"Mid Level", category:"Case Study", difficulty:"Hard", question:"How would you lead a requirements discovery process for a digital transformation initiative?", hint:"Stakeholder mapping, current state, future state vision, gap analysis, prioritization, governance." },

  { id:651, role:"Business Analyst", level:"Senior Level", category:"Technical", difficulty:"Easy", question:"What is enterprise architecture and how does a BA contribute to it?", hint:"TOGAF, business-IT alignment, capability model, BA ensures business requirements drive architecture." },
  { id:652, role:"Business Analyst", level:"Senior Level", category:"Technical", difficulty:"Medium", question:"How do you model business capabilities vs business processes? What's the difference?", hint:"Capability: what the business does (stable). Process: how it's done (variable). Capability map precedes process." },
  { id:653, role:"Business Analyst", level:"Senior Level", category:"Technical", difficulty:"Hard", question:"What is gap analysis and how would you apply it to a strategic transformation?", hint:"Current state assessment, target state vision, gap identification, root cause, prioritized roadmap." },
  { id:654, role:"Business Analyst", level:"Senior Level", category:"Behavioral", difficulty:"Easy", question:"How do you ensure that business analysis deliverables are valuable, not just thorough?", hint:"Outcome focus, JFDI principle for small things, ask 'what decision does this enable?' for every doc." },
  { id:655, role:"Business Analyst", level:"Senior Level", category:"Behavioral", difficulty:"Medium", question:"Tell me about a time you influenced a major strategic decision through your analysis.", hint:"What you analyzed, how you presented it, the resistance you faced, the outcome, what you learned." },
  { id:656, role:"Business Analyst", level:"Senior Level", category:"Behavioral", difficulty:"Hard", question:"How have you built a business analysis practice or Center of Excellence?", hint:"Standards, templates, training, community of practice, metrics, tool adoption, executive sponsorship." },
  { id:657, role:"Business Analyst", level:"Senior Level", category:"Situational", difficulty:"Easy", question:"You're asked to lead requirements for a project that spans 5 business departments. How do you start?", hint:"Stakeholder map, governance model, kickoff with all parties, single backlog, clear ownership." },
  { id:658, role:"Business Analyst", level:"Senior Level", category:"Situational", difficulty:"Medium", question:"The business wants a solution in 6 weeks that you estimate will take 6 months. How do you proceed?", hint:"MVP scoping, phased delivery, risk communication, negotiate must-haves, document and get sign-off." },
  { id:659, role:"Business Analyst", level:"Senior Level", category:"Situational", difficulty:"Hard", question:"A project you've been leading has uncovered significant regulatory compliance risks. How do you handle this?", hint:"Immediate escalation, involve legal/compliance, document findings, assess impact, recommend path forward." },
  { id:660, role:"Business Analyst", level:"Senior Level", category:"Culture Fit", difficulty:"Easy", question:"How do you ensure your BA practice stays relevant as organizations adopt agile?", hint:"Lean requirements, embedded in teams, JFDI for small things, story mapping, T-shaped skills." },
  { id:661, role:"Business Analyst", level:"Senior Level", category:"Culture Fit", difficulty:"Medium", question:"How do you coach less experienced BAs on your team?", hint:"Shadowing, co-facilitate workshops, feedback on deliverables, pair on complex stakeholders, career goals." },
  { id:662, role:"Business Analyst", level:"Senior Level", category:"Culture Fit", difficulty:"Hard", question:"How do you balance being an advocate for users vs. delivering business value as a BA?", hint:"Users and business are often aligned. Frame user needs as business risk. Use data to bridge the gap." },
  { id:663, role:"Business Analyst", level:"Senior Level", category:"Case Study", difficulty:"Easy", question:"How would you conduct a business impact assessment for a major system change?", hint:"Affected processes, stakeholders, data, integrations, risk levels, mitigation, communication plan." },
  { id:664, role:"Business Analyst", level:"Senior Level", category:"Case Study", difficulty:"Medium", question:"How would you design a requirements management process for a 12-month enterprise program?", hint:"Requirements tiers, traceability matrix, change control, sprint integration, sign-off process, tooling." },
  { id:665, role:"Business Analyst", level:"Senior Level", category:"Case Study", difficulty:"Hard", question:"You're leading the business analysis for a company merger. What are the key workstreams?", hint:"Process harmonization, system integration, data migration, org design impacts, regulatory, communication." },

  { id:666, role:"Business Analyst", level:"Lead / Manager", category:"Technical", difficulty:"Easy", question:"How do you choose the right requirements tool for a large BA team?", hint:"Team size, agile vs waterfall, integrations, traceability, collaboration, cost, training burden." },
  { id:667, role:"Business Analyst", level:"Lead / Manager", category:"Technical", difficulty:"Medium", question:"How do you ensure quality and consistency across BA deliverables in a large team?", hint:"Templates, peer review, standards documentation, training, community of practice, retrospectives." },
  { id:668, role:"Business Analyst", level:"Lead / Manager", category:"Technical", difficulty:"Hard", question:"How do you build a business analysis capability that supports both agile and waterfall delivery models?", hint:"Context-based approach, shared skills, method toolbox, situational frameworks, training." },
  { id:669, role:"Business Analyst", level:"Lead / Manager", category:"Behavioral", difficulty:"Easy", question:"How do you hire and develop business analysts?", hint:"Look for curiosity, communication, analytical rigor, business acumen, facilitation skills." },
  { id:670, role:"Business Analyst", level:"Lead / Manager", category:"Behavioral", difficulty:"Medium", question:"How do you manage a team of BAs across multiple simultaneous projects?", hint:"Capacity planning, priority alignment, escalation path, shared tools, knowledge sharing, 1:1s." },
  { id:671, role:"Business Analyst", level:"Lead / Manager", category:"Behavioral", difficulty:"Hard", question:"Tell me about a time you elevated the strategic impact of the BA function in an organization.", hint:"From order-taker to advisor, exec relationships, proactive insights, influence on strategy, metrics." },
  { id:672, role:"Business Analyst", level:"Lead / Manager", category:"Situational", difficulty:"Easy", question:"Your BA team is seen as a bottleneck by development teams. How do you address this?", hint:"Root cause (capacity? process?), streamline handoffs, self-service tools, remove unnecessary formality." },
  { id:673, role:"Business Analyst", level:"Lead / Manager", category:"Situational", difficulty:"Medium", question:"A senior BA on your team consistently delivers incomplete requirements that cause rework. What do you do?", hint:"Direct feedback, specific examples, expectation setting, support/training, document, performance plan." },
  { id:674, role:"Business Analyst", level:"Lead / Manager", category:"Situational", difficulty:"Hard", question:"Leadership wants to eliminate the BA function and have PMs do requirements. How do you make the case to keep it?", hint:"Quantify value (rework reduced, defects prevented), specialization argument, PM capacity, data." },
  { id:675, role:"Business Analyst", level:"Lead / Manager", category:"Culture Fit", difficulty:"Easy", question:"What does a high-performing BA team culture look like to you?", hint:"Curiosity, rigor, collaboration, outcome focus, continuous improvement, trusted by stakeholders." },
  { id:676, role:"Business Analyst", level:"Lead / Manager", category:"Culture Fit", difficulty:"Medium", question:"How do you foster continuous learning and development on your BA team?", hint:"CoP, conference attendance, internal knowledge sharing, shadowing, certifications, reading groups." },
  { id:677, role:"Business Analyst", level:"Lead / Manager", category:"Culture Fit", difficulty:"Hard", question:"How do you create a culture where BAs are seen as strategic partners rather than documentation writers?", hint:"Executive access, proactive insights, BA in strategy sessions, metrics on business outcomes." },
  { id:678, role:"Business Analyst", level:"Lead / Manager", category:"Case Study", difficulty:"Easy", question:"How would you set up a BA practice for a startup that has never had one?", hint:"Start lean, focus on discovery, templates over process, embed in teams, demonstrate value early." },
  { id:679, role:"Business Analyst", level:"Lead / Manager", category:"Case Study", difficulty:"Medium", question:"Design an onboarding program for new BAs joining a large consulting firm.", hint:"Methods training, shadowing, client context, tools, first assignment with support, 90-day milestones." },
  { id:680, role:"Business Analyst", level:"Lead / Manager", category:"Case Study", difficulty:"Hard", question:"How would you build a BA Center of Excellence for a 5000-person enterprise?", hint:"Mission, governance, standards library, training curriculum, tooling, community, executive sponsorship, metrics." }

